insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('someone-elses-surgery-day-waiting-plan-sheet', 'Someone Else''s Surgery Day Waiting Plan Sheet', 'worksheet'::resource_kind, 'A plan for the hours a client spends waiting while a family member or friend is in surgery.', 'Use it to give a client a shape for a long, helpless wait so the day is not spent staring at a door.', array['Adults']::text[], '30 minutes to prepare, used on the day', 'A surgery day is a long wait with nothing to do and a great deal at stake, and most clients arrive with no plan beyond showing up. Walk through the day in hour blocks: who else will be there, what the client will eat, where they can step outside, who they will text updates to, and what they will do with their hands. Ask what the client will tell themselves if the update is late, since late updates are common and usually mean nothing. Watch for a client who plans to do nothing but watch the door, and help them pick two small tasks.', '[{"id": "f0", "type": "textarea", "label": "The day and the time I expect to be waiting, and who will be with me:"}, {"id": "f1", "type": "textarea", "label": "Hour by hour: what I will do with the first hour, the second, and the ones after:"}, {"id": "f2", "type": "textarea", "label": "What I will eat and drink, and where I can step outside for five minutes:"}, {"id": "f3", "type": "textarea", "label": "Who I will send updates to, and one person I can call if the wait gets long:"}, {"id": "f4", "type": "textarea", "label": "What I will tell myself if the update is later than promised:"}, {"id": "f5", "type": "textarea", "label": "Afterward: what helped, what I would change for a day like this:"}]'::jsonb, array['stress', 'planning', 'support']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('noisy-upstairs-neighbor-next-step-decision-sheet', 'Noisy Upstairs Neighbor Next Step Decision Sheet', 'worksheet'::resource_kind, 'A decision sheet for a client worn down by noise from a neighbor, sorting the options from a note to a move.', 'Use it to turn months of stewing about a neighbor into one chosen next step the client can actually take.', array['Adults']::text[], '25 minutes', 'Noise from a neighbor is a small problem that becomes a large one because it recurs every night and the client feels powerless about it. The sheet lays out the options the client has been circling (say nothing, leave a note, knock, talk to the landlord, soundproof, move), and for each one the client writes the likely result and the cost. Then they pick the next step, not the final one, and the day they will take it.', '[{"id": "f0", "type": "textarea", "label": "The noise, when it happens, and how it is affecting my sleep, mood or evenings:"}, {"id": "f1", "type": "textarea", "label": "Everything I could do about it, including doing nothing:"}, {"id": "f2", "type": "textarea", "label": "For each option: what would probably happen, and what it would cost me:"}, {"id": "f3", "type": "textarea", "label": "The one next step I am choosing, and the day I will take it:"}, {"id": "f4", "type": "textarea", "label": "If I am speaking to the neighbor or landlord: my first two sentences:"}, {"id": "f5", "type": "textarea", "label": "After the step: what happened, and what the step after that might be:"}]'::jsonb, array['conflict', 'decisions', 'assertiveness']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('credit-card-statement-review-without-the-spiral-sheet', 'Credit Card Statement Review Without the Spiral Sheet', 'worksheet'::resource_kind, 'A paced walk through a credit card statement for a client who avoids opening it or spirals once they do.', 'Use it to help a client read a statement line by line with a plan for the feelings, instead of avoiding it or panicking.', array['Adults']::text[], '30 minutes, with the statement in hand', 'Many clients either never open the statement or open it and lose the evening to self-blame. The sheet puts the review in session or at a set time at home: before opening it, the client guesses the total and names the feeling they expect; then they go through the lines and sort them into needed, chosen and forgotten; then they write one next step, such as canceling one forgotten charge. Keep the client to facts and one step. Watch for the jump from the total to a verdict on themselves; the sheet has a line for that verdict so it can be looked at rather than obeyed.', '[{"id": "f0", "type": "textarea", "label": "Before I open it: my guess at the total, and the feeling I expect:"}, {"id": "f1", "type": "textarea", "label": "The actual total, and how far off my guess was:"}, {"id": "f2", "type": "textarea", "label": "Line by line: charges that were needed, charges I chose, and charges I had forgotten about:"}, {"id": "f3", "type": "textarea", "label": "The verdict my mind passed on me while reading, written out as a sentence:"}, {"id": "f4", "type": "textarea", "label": "One next step about the money, small enough to do this week:"}, {"id": "f5", "type": "textarea", "label": "What I will do for the rest of the evening after closing the statement:"}]'::jsonb, array['money', 'avoidance', 'self-monitoring']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('elderly-parent-driving-talk-prep-sheet', 'Elderly Parent Driving Talk Prep Sheet', 'worksheet'::resource_kind, 'A preparation sheet for the conversation with an aging parent about whether they should still be driving.', 'Use it to help a client plan a hard, loving conversation with a parent about driving instead of putting it off.', array['Adults']::text[], '40 minutes', 'Clients dread this conversation because it threatens a parent''s independence and often ends in anger. The sheet has the client write down what they have actually seen (not what they fear), what the parent stands to lose if they stop driving and how each loss could be replaced, who else should be in the conversation, and what they will say in the first minute. It also asks what they will do if the parent refuses, because many do, and a refusal is not the end of the matter.', '[{"id": "f0", "type": "textarea", "label": "What I have actually seen while they were driving, with dates if I can:"}, {"id": "f1", "type": "textarea", "label": "What they would lose if they stopped driving, and how each loss could be replaced:"}, {"id": "f2", "type": "textarea", "label": "Who should be in this conversation with me, and who should not:"}, {"id": "f3", "type": "textarea", "label": "My first minute: a question and one specific observation, not a conclusion:"}, {"id": "f4", "type": "textarea", "label": "If they refuse: what I will do next, and who I can involve:"}, {"id": "f5", "type": "textarea", "label": "After the conversation: what was said, and what I will do in the next two weeks:"}]'::jsonb, array['family', 'communication', 'planning']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('wedding-guest-weekend-energy-budget-sheet', 'Wedding Guest Weekend Energy Budget Sheet', 'worksheet'::resource_kind, 'An energy budget for a wedding weekend: rehearsal dinner, ceremony, reception and brunch, with planned breaks.', 'Use it to help a client get through a long social weekend by planning where the energy goes and where it is refilled.', array['Adults']::text[], '25 minutes before the weekend', 'A wedding weekend can be three days of events with a client who runs out of social energy after three hours. The sheet lists each event, the client''s guess at how much it will take, and what they will do between events to recover: a walk, an hour alone in the hotel room, a skipped brunch. The point is to spend energy on purpose, not to avoid the weekend. Help the client notice where they have budgeted no recovery at all and where they could leave an event early without anyone minding.', '[{"id": "f0", "type": "textarea", "label": "Each event of the weekend, and my guess at how much energy it will take (1 to 10):"}, {"id": "f1", "type": "textarea", "label": "Where I will recover between events, and for how long:"}, {"id": "f2", "type": "textarea", "label": "The events I could leave early, and what I will say when I go:"}, {"id": "f3", "type": "textarea", "label": "Who at the wedding refills my energy, and who drains it:"}, {"id": "f4", "type": "textarea", "label": "The one moment of the weekend I most want to be present for:"}, {"id": "f5", "type": "textarea", "label": "Afterward: what each event actually took, and what I would budget differently:"}]'::jsonb, array['planning', 'energy', 'boundaries']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('friends-posted-a-photo-without-me-thought-record', 'Friends Posted a Photo Without Me Thought Record', 'cbt'::resource_kind, 'A thought record for the moment a client sees a photo of friends together at something they were not invited to.', 'Use it to catch the automatic thoughts that follow seeing friends together online and weigh them against the facts.', array['Adults', 'Teens']::text[], '20 minutes', 'The photo appears, the stomach drops, and within seconds the client has a story: they are being left out, the friendship is over, everyone else is closer. The record has them write the situation plainly, the hot thought and how much they believed it, the feelings, and then the evidence for and against, including the explanations that have nothing to do with them (a last-minute plan, a group from work, a photo from months ago). Watch for a client who treats the photo as proof; the record asks what they would need to know to be sure, and whether they could simply ask.', '[{"id": "f0", "type": "textarea", "label": "What I saw, where, and when:"}, {"id": "f1", "type": "textarea", "label": "The first thought that went through my mind, and how much I believed it (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "What I felt, and how strongly (0 to 100):"}, {"id": "f3", "type": "textarea", "label": "Evidence that the thought is true:"}, {"id": "f4", "type": "textarea", "label": "Evidence against it, including explanations that have nothing to do with me:"}, {"id": "f5", "type": "textarea", "label": "A balanced thought I can stand behind, and my belief in the first thought now:"}, {"id": "f6", "type": "textarea", "label": "What I will do: nothing, ask about it, or make my own plan with one of them:"}]'::jsonb, array['thought record', 'thinking traps', 'relationships']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('waiter-brought-the-wrong-order-personalization-check-sheet', 'Waiter Brought the Wrong Order Personalization Check Sheet', 'cbt'::resource_kind, 'A check sheet for the small public mishap that a client reads as being about them.', 'Use it to catch personalization in an everyday mix-up and practice the explanations that leave the client out of it.', array['Adults', 'Teens']::text[], '15 minutes', 'The wrong plate arrives and the client''s mind says the waiter did not like them, or they ordered badly, or they will cause a scene if they say anything. The sheet takes the mix-up apart: what happened, the thought that made it about the client, and then at least three explanations that are about the kitchen, the night or chance. The client rates how much each explanation fits and then writes what they will do, which is usually to say so politely. Watch for a client who eats the wrong meal rather than speak, and treat the speaking as the behavioral piece.', '[{"id": "f0", "type": "textarea", "label": "The mix-up: what happened, and where:"}, {"id": "f1", "type": "textarea", "label": "The thought that made it about me:"}, {"id": "f2", "type": "textarea", "label": "Three explanations that have nothing to do with me:"}, {"id": "f3", "type": "textarea", "label": "How much each explanation fits, out of 100, next to how much mine does:"}, {"id": "f4", "type": "textarea", "label": "What I did, or will do next time, in one plain sentence to the person:"}, {"id": "f5", "type": "textarea", "label": "Other small mishaps this week that I made about me:"}]'::jsonb, array['thinking traps', 'core CBT', 'personalization']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('half-the-chores-done-counts-as-nothing-sheet', 'Half the Chores Done Counts as Nothing Sheet', 'cbt'::resource_kind, 'An all-or-nothing check for the client who rates a half-finished list as a failure.', 'Use it to show a client the gap between a partly done day and a wasted one, and to rate the day on a scale.', array['Adults', 'Teens']::text[], '15 minutes', 'Clients who think in all-or-nothing terms look at a list with four items crossed off and three left and call the day a waste. The sheet has them write the list as it stood at the end of the day, the verdict their mind passed, and then rate the day on a scale from zero to ten rather than pass or fail. The second half asks what the verdict cost them: often the three undone items become six the next day because the day was already written off. Watch for the client who moves the goalposts, deciding the done items did not count because they were easy.', '[{"id": "f0", "type": "textarea", "label": "Today''s list as it stood at bedtime: what was done, what was not:"}, {"id": "f1", "type": "textarea", "label": "The verdict my mind passed on the day, in its own words:"}, {"id": "f2", "type": "textarea", "label": "The day on a scale from 0 to 10, and why that number:"}, {"id": "f3", "type": "textarea", "label": "What a friend would say about this list:"}, {"id": "f4", "type": "textarea", "label": "What the all-or-nothing verdict cost me tonight or tomorrow:"}, {"id": "f5", "type": "textarea", "label": "A rule for rating days that I could actually live by:"}]'::jsonb, array['thinking traps', 'core CBT', 'all-or-nothing']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('ask-a-neighbor-to-borrow-a-ladder-experiment-sheet', 'Ask a Neighbor to Borrow a Ladder Experiment Sheet', 'cbt'::resource_kind, 'A behavioral experiment in asking a neighbor for a small favor, with predictions written down and tested.', 'Use it to test a client''s prediction that asking for help will annoy people, in a low-stakes everyday request.', array['Adults']::text[], '20 minutes to set up, 10 minutes to debrief', 'A client who never asks for anything usually has a clear prediction about what happens when they do. The experiment is to ask a neighbor to borrow something small (a ladder, a drill, a cup of sugar) and to write the prediction first: how the neighbor will react, how awkward it will be, how long the awkwardness will last. Then the client does it and records what actually happened. Help the client choose a neighbor who is likely to be ordinary rather than hostile, since the point is to test the rule, not to survive the worst case.', '[{"id": "f0", "type": "textarea", "label": "What I will ask for, from whom, and when:"}, {"id": "f1", "type": "textarea", "label": "My prediction: how they will react, and how awkward it will be (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "How long I predict the awkwardness will last afterward:"}, {"id": "f3", "type": "textarea", "label": "What actually happened, in their words and mine:"}, {"id": "f4", "type": "textarea", "label": "How awkward it actually was (0 to 100), and for how long:"}, {"id": "f5", "type": "textarea", "label": "What this tells me about the rule I have been living by, and the next small ask:"}]'::jsonb, array['behavioral experiment', 'predictions', 'assertiveness']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('pottery-class-lopsided-bowl-thought-record', 'Pottery Class Lopsided Bowl Thought Record', 'cbt'::resource_kind, 'A thought record for the beginner''s moment when a new hobby produces something imperfect in front of others.', 'Use it to catch the self-critical thoughts that turn a beginner''s wobbly result into a reason to quit.', array['Adults', 'Teens']::text[], '20 minutes', 'Clients start hobbies to enjoy themselves and quit when the first results are poor, and the thoughts in between are worth recording. The sheet captures the moment (the lopsided bowl, the off-key song, the fallen souffle), the automatic thought, and the feeling, then asks for the evidence: what beginners'' work usually looks like, what the teacher said, what the client would say to another beginner. Then a balanced thought and a decision about the next class. Watch for the thought that other beginners are better; the sheet asks for actual observations rather than impressions.', '[{"id": "f0", "type": "textarea", "label": "The moment: what I made, and who saw it:"}, {"id": "f1", "type": "textarea", "label": "The thought that went through my mind, and how much I believed it:"}, {"id": "f2", "type": "textarea", "label": "What I felt, and how strongly:"}, {"id": "f3", "type": "textarea", "label": "What beginners'' work usually looks like, and what the teacher or others actually said:"}, {"id": "f4", "type": "textarea", "label": "What I would say to another beginner who made this:"}, {"id": "f5", "type": "textarea", "label": "A balanced thought, and whether I am going to the next class:"}]'::jsonb, array['thought record', 'perfectionism', 'self-criticism']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('mind-as-a-group-chat-that-never-goes-quiet-page', 'Mind as a Group Chat That Never Goes Quiet Page', 'act'::resource_kind, 'A defusion page that treats the mind''s chatter as a group chat the client can read without replying to.', 'Use it to give a client a way to notice a stream of thoughts without answering every one of them.', array['Adults', 'Teens']::text[], '15 minutes', 'Most clients know a group chat that pings all day, where nobody expects a reply to every message. The page asks the client to picture their mind the same way: thoughts arrive, some from the same few loud members, and the client can read them, mute them for an hour, or let the thread scroll without typing. They list the usual members (the critic, the planner, the one who brings up old arguments), note which messages they feel compelled to answer, and practice letting three go unanswered. Watch for a client who treats muting as suppression; the messages still arrive, they are just not answered.', '[{"id": "f0", "type": "textarea", "label": "The loudest members of my mind''s group chat, and what each one usually posts:"}, {"id": "f1", "type": "textarea", "label": "The kinds of messages I feel I have to answer right away:"}, {"id": "f2", "type": "textarea", "label": "Three messages this week I read and let scroll past without replying:"}, {"id": "f3", "type": "textarea", "label": "What it was like to leave them unanswered:"}, {"id": "f4", "type": "textarea", "label": "What I did with the time I did not spend replying:"}, {"id": "f5", "type": "textarea", "label": "What I would call this group chat if it had a name:"}]'::jsonb, array['defusion', 'metaphor', 'core ACT']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('values-as-the-riverbank-not-the-river-page', 'Values as the Riverbank Not the River Page', 'act'::resource_kind, 'A values page using the riverbank as the steady thing that shapes a life while the feelings flow through.', 'Use it to help a client separate what they want to stand for from the feelings that change hour to hour.', array['Adults', 'Teens']::text[], '20 minutes', 'Clients often try to build a plan on how they feel, and the plan washes away when the feeling changes. The page offers a different picture: feelings are the river, fast or slow, muddy or clear, and values are the banks that give it a direction. The client names the river this week, then the banks they want to hold whatever the water does, then one place where the river has been cutting into the bank. Watch for a client who writes feelings as values (I want to be happy); ask what they would be doing on a happy day, and write that.', '[{"id": "f0", "type": "textarea", "label": "The river this week: the feelings that have been flowing through, fast or slow:"}, {"id": "f1", "type": "textarea", "label": "The banks: what I want to stand for no matter what the water does:"}, {"id": "f2", "type": "textarea", "label": "One place where the river has been cutting into the bank lately:"}, {"id": "f3", "type": "textarea", "label": "A small action this week that shores up the bank, whatever I feel that day:"}, {"id": "f4", "type": "textarea", "label": "How I will know the banks held, even if the water was rough:"}]'::jsonb, array['values', 'metaphor', 'committed action']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('hiking-with-a-full-pack-willingness-page', 'Hiking With a Full Pack Willingness Page', 'act'::resource_kind, 'A willingness page that pictures hard feelings as a loaded pack the client carries up a trail they chose.', 'Use it to help a client separate carrying discomfort from being stopped by it, with a real trail in mind.', array['Adults', 'Teens']::text[], '15 minutes', 'The page has the client name the trail (the thing they want to do), what is in the pack (the feelings that come with it), and what they have been doing instead of walking: setting the pack down and waiting for it to get lighter, or arguing about whether it should be this heavy. Then they adjust the straps, which means naming what makes the carrying more bearable, and take the next hundred yards. Watch for a client who wants to empty the pack first; the page is about walking with it.', '[{"id": "f0", "type": "textarea", "label": "The trail: what I want to do that comes with a heavy pack:"}, {"id": "f1", "type": "textarea", "label": "What is in the pack: the feelings and thoughts that come along:"}, {"id": "f2", "type": "textarea", "label": "What I have been doing instead of walking: waiting for it to lighten, arguing with the weight:"}, {"id": "f3", "type": "textarea", "label": "Adjusting the straps: what makes the carrying more bearable without putting it down:"}, {"id": "f4", "type": "textarea", "label": "The next hundred yards: the first small stretch I will walk this week:"}, {"id": "f5", "type": "textarea", "label": "The view: what I am walking toward that makes the weight worth it:"}]'::jsonb, array['willingness', 'metaphor', 'committed action']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('clock-watcher-at-the-kids-recital-present-moment-page', 'Clock Watcher at the Kids'' Recital Present Moment Page', 'act'::resource_kind, 'A present-moment page for the client who is physically at the event and mentally at the exit.', 'Use it to help a client notice when they have left an event in their head and practice coming back to it.', array['Adults']::text[], '15 minutes', 'The recital, the game, the long dinner: the client is there, checking the time, planning the drive home, and misses the thing they came for. The page has the client pick an upcoming event they expect to drift through, write the places their mind usually goes, and choose three anchors to return to: the sound in the room, the face of the person they came for, their own feet on the floor. Afterward they record how often they came back, and one moment they would have missed. Watch for a client who scores themselves on how little they drifted rather than on how often they returned.', '[{"id": "f0", "type": "textarea", "label": "The upcoming event I expect to sit through while my mind is elsewhere:"}, {"id": "f1", "type": "textarea", "label": "Where my mind usually goes: the exit, the clock, tomorrow''s list:"}, {"id": "f2", "type": "textarea", "label": "Three anchors in the room I will return to when I notice I have drifted:"}, {"id": "f3", "type": "textarea", "label": "Afterward: how many times I noticed I had left and came back:"}, {"id": "f4", "type": "textarea", "label": "One moment I would have missed if I had not come back:"}, {"id": "f5", "type": "textarea", "label": "The next event where I will practice this:"}]'::jsonb, array['present moment', 'mindfulness', 'values']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('minds-objection-to-every-plan-noticing-page', 'Mind''s Objection to Every Plan Noticing Page', 'act'::resource_kind, 'A defusion page for the mind that answers every plan with a reason it will not work.', 'Use it to help a client hear the objection, thank the mind, and carry on with the plan anyway.', array['Adults', 'Teens']::text[], '15 minutes', 'Some minds reply to every intention with an objection: too tired, too late, not the right day, what if it goes badly. The page has the client write a plan they have made and then every objection the mind raised, word for word, as a list. Then they look at the list and mark which objections are information worth acting on and which are the mind doing its usual job. For the usual ones they practice a short reply (thanks, mind) and keep the plan. Watch for a client who argues with each objection in turn; the practice is to notice the pattern, not win the debate.', '[{"id": "f0", "type": "textarea", "label": "The plan I made, in one sentence:"}, {"id": "f1", "type": "textarea", "label": "Every objection my mind raised, word for word, as a list:"}, {"id": "f2", "type": "textarea", "label": "Which objections are real information, and which are the mind doing its usual job:"}, {"id": "f3", "type": "textarea", "label": "The short reply I will give the usual ones:"}, {"id": "f4", "type": "textarea", "label": "Whether the plan happened, and what the mind said while I did it:"}, {"id": "f5", "type": "textarea", "label": "What I notice about the objections now that they are on paper:"}]'::jsonb, array['defusion', 'committed action', 'core ACT']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('stop-skill-before-hitting-reply-all-card', 'STOP Skill Before Hitting Reply All Card', 'dbt'::resource_kind, 'A STOP skill card for the moment a client is about to send a heated reply to a whole thread.', 'Use it to put a pause between a client''s flash of anger at an email and the reply that everyone will read.', array['Adults']::text[], '10 minutes to prepare, used in the moment', 'The STOP skill is Stop, Take a step back, Observe, Proceed mindfully, and the reply-all button is where many clients need it most. The card has them write the kind of email that sets them off, what Stop looks like at a desk (hands off the keyboard, draft saved), how they will take a step back (a walk to the water cooler, one hour), what they will observe (the body, the urge, the facts of the email), and how they will proceed: reply to one person, reply later, or not at all. Watch for the client who skips to proceed; the step back is the skill.', '[{"id": "f0", "type": "textarea", "label": "The kind of email or message that makes me want to reply all right away:"}, {"id": "f1", "type": "textarea", "label": "Stop: what I will do with my hands and the draft the moment I notice the urge:"}, {"id": "f2", "type": "textarea", "label": "Take a step back: where I will go, and for how long:"}, {"id": "f3", "type": "textarea", "label": "Observe: what I notice in my body, the urge, and the actual facts of the message:"}, {"id": "f4", "type": "textarea", "label": "Proceed mindfully: reply to one person, reply later, or let it go:"}, {"id": "f5", "type": "textarea", "label": "A recent email where I used this, or wish I had, and how it went:"}]'::jsonb, array['STOP', 'interpersonal effectiveness', 'work']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('tipp-intense-exercise-two-flights-of-stairs-card', 'TIPP Intense Exercise Two Flights of Stairs Card', 'dbt'::resource_kind, 'A TIPP card that uses two flights of stairs as the intense exercise to bring a surge of emotion down fast.', 'Use it to give a client a short burst of movement they can do almost anywhere when emotion is running high.', array['Adults', 'Teens']::text[], '5 minutes to prepare, used in the moment', 'The I in TIPP is intense exercise, and stairs are available in most buildings. The card has the client find the stairs where they spend their days (work, school, home, the parking garage), decide how many flights they will climb and at what pace, and note what they will tell anyone who asks. They rate the emotion before and after, and write what they will do once they are back down. Check that the client''s health allows a brisk climb and adjust the pace or the count if not. Watch for the client who uses the stairs to flee the situation; the card has them return to it afterward.', '[{"id": "f0", "type": "textarea", "label": "Where the nearest stairs are in the places I spend my days:"}, {"id": "f1", "type": "textarea", "label": "How many flights I will climb, at what pace, and what I will say if someone asks:"}, {"id": "f2", "type": "textarea", "label": "The emotion before the climb, 0 to 100, and what my body was doing:"}, {"id": "f3", "type": "textarea", "label": "The emotion after, 0 to 100, and what changed in my body:"}, {"id": "f4", "type": "textarea", "label": "What I did when I came back down and returned to the situation:"}, {"id": "f5", "type": "textarea", "label": "Other short bursts of movement I could use when there are no stairs:"}]'::jsonb, array['TIPP', 'distress tolerance', 'core DBT']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('validation-levels-for-a-friends-work-vent-sheet', 'Validation Levels for a Friend''s Work Vent Sheet', 'dbt'::resource_kind, 'A practice sheet applying the six levels of validation to a friend''s complaints about their job.', 'Use it to help a client practice validating without fixing, on the everyday case of a friend who needs to vent.', array['Adults', 'Teens']::text[], '20 minutes', 'A friend vents about work and the client either solves, dismisses or matches the complaint with their own. The sheet takes one recent vent and has the client write a response at each level: paying attention, reflecting back, reading what was unsaid, validating from the friend''s history, validating from the facts, and being genuine. Then they pick the level that would have fit and write what they actually said. Watch for the client who skips to level six and gives advice; the practice is to earn the right to advise by validating first, and often the advice turns out not to be wanted.', '[{"id": "f0", "type": "textarea", "label": "The vent: what my friend was complaining about, in a few lines:"}, {"id": "f1", "type": "textarea", "label": "Level 1 and 2: how I showed I was listening, and what I reflected back:"}, {"id": "f2", "type": "textarea", "label": "Level 3: what they were feeling that they did not say:"}, {"id": "f3", "type": "textarea", "label": "Level 4 and 5: why it makes sense given their history, and why it makes sense given the facts:"}, {"id": "f4", "type": "textarea", "label": "Level 6: what I would say as an equal who takes them seriously:"}, {"id": "f5", "type": "textarea", "label": "What I actually said, which level it was, and what I will try next time:"}]'::jsonb, array['validation', 'interpersonal effectiveness', 'core DBT']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('build-mastery-with-a-recipe-i-have-never-cooked-card', 'Build Mastery With a Recipe I Have Never Cooked Card', 'dbt'::resource_kind, 'A build mastery card that uses one new recipe a week as a small, finishable challenge.', 'Use it to give a client a weekly task that is slightly hard, ends with something to show, and builds confidence.', array['Adults', 'Teens']::text[], 'One recipe a week for a month', 'Build mastery asks for one thing a day that is a little difficult and gets done, and a new recipe fits: it has a start, an end, a result on a plate, and a chance to be slightly bad at something. The card has the client pick a recipe just beyond what they usually cook, note what makes it a stretch, and after cooking write what went wrong, what they would change, and the sense of mastery on a scale. Watch for a client who picks something far too hard or who rates the dish rather than the doing; the skill is in finishing, not in the food.', '[{"id": "f0", "type": "textarea", "label": "The recipe for this week, and what makes it a stretch for me:"}, {"id": "f1", "type": "textarea", "label": "When I will cook it, and what I need to buy first:"}, {"id": "f2", "type": "textarea", "label": "What went wrong, and what I would change next time:"}, {"id": "f3", "type": "textarea", "label": "How finished it felt, and my sense of mastery afterward (0 to 10):"}, {"id": "f4", "type": "textarea", "label": "Who ate it, or what I did with it:"}, {"id": "f5", "type": "textarea", "label": "The recipe for next week, a little harder or a little different:"}]'::jsonb, array['build mastery', 'emotion regulation', 'core DBT']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('radical-acceptance-of-the-canceled-flight-card', 'Radical Acceptance of the Canceled Flight Card', 'dbt'::resource_kind, 'A radical acceptance card for the airport announcement that undoes a client''s plans for the day.', 'Use it to help a client move from fighting a canceled flight to deciding what to do with the day they now have.', array['Adults']::text[], '10 minutes to prepare, used at the gate', 'A canceled flight is a clean example of a fact that will not change however the client feels about it. The card walks through radical acceptance in the moment: naming the fact, noticing the fight against it (the should, the unfairness, the replaying of what they could have done), the body during the fight, and then the turning toward what is: this is the situation, and here is what I will do in the next hour. Watch for a client who confuses acceptance with approval or passivity; they can still rebook, complain and ask for a voucher while accepting that the flight is gone.', '[{"id": "f0", "type": "textarea", "label": "The fact I cannot change, in one plain sentence:"}, {"id": "f1", "type": "textarea", "label": "The fight against it: the should statements, the unfairness, the replay:"}, {"id": "f2", "type": "textarea", "label": "What my body is doing while I fight it:"}, {"id": "f3", "type": "textarea", "label": "The turning: the sentence I will say to myself to face what is:"}, {"id": "f4", "type": "textarea", "label": "What I can still do about it (rebook, ask for a voucher, call ahead), and what I cannot:"}, {"id": "f5", "type": "textarea", "label": "What I will do with the next hour of the day I now have:"}]'::jsonb, array['radical acceptance', 'distress tolerance', 'travel']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('kitchen-renovation-decision-load-sheet-for-partners', 'Kitchen Renovation Decision Load Sheet for Partners', 'couples'::resource_kind, 'A sheet for a couple in the middle of a renovation, splitting the decisions and the fights they keep having.', 'Use it to help partners share the hundred decisions of a renovation without every tile becoming a referendum.', array['Couples']::text[], '45 minutes', 'A renovation is months of decisions under budget pressure, and couples often arrive exhausted and bickering about faucets. The sheet has each partner list the decisions still open, mark which ones they care about and which they would hand over, and name the fight they keep having underneath (money, taste, who does the research, who talks to the contractor), then divide the decisions and set a weekly half hour for renovation talk. Watch for one partner who cares about everything and one who has checked out; the sheet asks each to name three decisions they will own.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the decisions still open, and which ones I care about versus would hand over:"}, {"id": "f1", "type": "textarea", "label": "Partner B: the decisions still open, and which ones I care about versus would hand over:"}, {"id": "f2", "type": "textarea", "label": "Together: the fight we keep having underneath the faucets, named plainly:"}, {"id": "f3", "type": "textarea", "label": "The decisions each of us will own alone, and the few that need both of us:"}, {"id": "f4", "type": "textarea", "label": "The weekly half hour when renovation talk happens, and the rule for the rest of the week:"}, {"id": "f5", "type": "textarea", "label": "Partner A and Partner B: one thing the other has done well in this project so far:"}]'::jsonb, array['couples', 'decisions', 'money']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('spiders-mice-and-dread-jobs-division-sheet-for-partners', 'Spiders Mice and Dread Jobs Division Sheet for Partners', 'couples'::resource_kind, 'A fairness sheet for the household jobs each partner dreads, from spiders to the clogged drain to the awkward phone call.', 'Use it to help partners trade the jobs each one hates so the dread is shared instead of landing on one person.', array['Couples']::text[], '30 minutes', 'Every household has jobs that nobody wants: the spider, the mouse, the drain, the phone call to the insurer, the dead bird in the yard. The sheet has each partner list the jobs they dread and rate the dread, then compare lists: often one partner''s dread job is the other''s shrug. They trade where they can, split the ones they both hate, and agree on what to say when a dread job comes up unplanned. Watch for a partner who dismisses the other''s dread as silly; the sheet has them write the dread out so it can be taken seriously.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the household jobs I dread, each rated 0 to 10:"}, {"id": "f1", "type": "textarea", "label": "Partner B: the household jobs I dread, each rated 0 to 10:"}, {"id": "f2", "type": "textarea", "label": "The trades: jobs one of us dreads that the other does not mind:"}, {"id": "f3", "type": "textarea", "label": "The jobs we both dread, and how we will split or share them:"}, {"id": "f4", "type": "textarea", "label": "What we will say when a dread job comes up unplanned, so it does not turn into a standoff:"}, {"id": "f5", "type": "textarea", "label": "After a month: which trades held, and which jobs still land on one person:"}]'::jsonb, array['couples', 'fairness', 'planning']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('meeting-each-others-coworkers-prep-sheet-for-partners', 'Meeting Each Other''s Coworkers Prep Sheet for Partners', 'couples'::resource_kind, 'A preparation sheet for a work event where one partner meets the other''s colleagues for the first time.', 'Use it to help partners agree on what the visiting partner needs to know, and how they will look after each other.', array['Couples']::text[], '25 minutes', 'The office party or team dinner puts one partner among strangers who all know each other, and the other partner between two worlds. The sheet has the host partner write who will be there and what the visitor should know (names, the one topic to avoid, the person who talks too long), and the visiting partner write what they need: an introduction, a check-in every half hour, a signal when they want to leave. Watch for the host partner disappearing into work talk; the sheet makes the check-ins explicit.', '[{"id": "f0", "type": "textarea", "label": "Host partner: who will be there, and what my partner should know about each person:"}, {"id": "f1", "type": "textarea", "label": "Host partner: the one topic to steer around, and how I will introduce my partner:"}, {"id": "f2", "type": "textarea", "label": "Visiting partner: what I need from you during the event, and how often:"}, {"id": "f3", "type": "textarea", "label": "Visiting partner: the signal I will give when I am ready to leave:"}, {"id": "f4", "type": "textarea", "label": "Together: arrival time, leaving time, and what each of us says to a question we would rather not answer:"}, {"id": "f5", "type": "textarea", "label": "Afterward: what went well, and what we would do differently at the next one:"}]'::jsonb, array['couples', 'support', 'planning']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('charging-cables-and-shared-tech-friction-pact-for-partners', 'Charging Cables and Shared Tech Friction Pact for Partners', 'couples'::resource_kind, 'A pact for the small daily tech frictions between partners: borrowed chargers, shared passwords, the remote, the thermostat app.', 'Use it to settle the recurring small tech frictions that take up more argument time than they deserve.', array['Couples']::text[], '25 minutes', 'The missing charger, the changed streaming profile, the logged-out account, the volume at midnight: small frictions that come up daily and are never settled. The sheet has each partner list their top three tech annoyances, name what the annoyance is really about (respect for my things, being left to fix everything, feeling watched), and then agree on a few plain rules: chargers that live in one place, whose profile is whose, how the shared password gets changed. Watch for a partner who says none of this matters; the one who keeps bringing it up is telling you it does.', '[{"id": "f0", "type": "textarea", "label": "Partner A: my three biggest small tech annoyances at home:"}, {"id": "f1", "type": "textarea", "label": "Partner B: my three biggest small tech annoyances at home:"}, {"id": "f2", "type": "textarea", "label": "Each of us: what the annoyance is really about underneath:"}, {"id": "f3", "type": "textarea", "label": "The plain rules we agree on, one line each:"}, {"id": "f4", "type": "textarea", "label": "What we will say when a rule is broken, so it is a reminder and not a fight:"}, {"id": "f5", "type": "textarea", "label": "After two weeks: which rules held, and which need rewriting:"}]'::jsonb, array['couples', 'conflict', 'communication']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('moving-in-together-first-month-agreements-sheet-for-partners', 'Moving In Together First Month Agreements Sheet for Partners', 'couples'::resource_kind, 'A first-month sheet for partners who have just moved in together, covering space, money, guests and alone time.', 'Use it to help a couple make the early agreements of living together on purpose instead of by collision.', array['Couples']::text[], '45 minutes', 'Couples who move in together often discover their expectations by tripping over them: one wants guests every weekend, the other wants Sunday alone; one pays bills on the first, the other on the last day. The sheet has each partner write what they expected about shared space, money, guests, chores and alone time, then compares. Where they differ, they write a first-month agreement to try, not a permanent rule, and set a date to review it. Watch for a partner who gives way on everything to avoid friction in the first month; the sheet asks each to name one thing they will not give up.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I expected about space, money, guests, chores and alone time:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I expected about space, money, guests, chores and alone time:"}, {"id": "f2", "type": "textarea", "label": "Where our expectations match, and where they collide:"}, {"id": "f3", "type": "textarea", "label": "Our first-month agreements for the collisions, one line each, to try rather than to keep forever:"}, {"id": "f4", "type": "textarea", "label": "Each of us: one thing I will not give up, even in the first month:"}, {"id": "f5", "type": "textarea", "label": "The date we review these, and what we will ask each other then:"}]'::jsonb, array['couples', 'transitions', 'boundaries']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('leaf-rubbing-slow-hands-craft', 'Leaf Rubbing Slow Hands Craft', 'kids'::resource_kind, 'A leaf rubbing craft where the child slows their hands and breath to bring up the pattern of a leaf.', 'Use it to give a child a quiet, slow-hands activity that settles the body while making something to keep.', array['Children']::text[], '25 minutes', 'The child collects a few leaves (or uses ones the parent brings), lays each under thin paper, and rubs a crayon slowly across it until the veins appear. Fast rubbing tears the paper, so the craft rewards slow hands and slow breath; the parent names that out loud (slow hands, slow breath) and does a leaf alongside the child. Then the child chooses a feeling for each leaf by color or shape and tells one sentence about it. Watch for a child who rushes and tears the paper; hand them a new sheet without comment and model the pace again.', '[{"id": "f0", "type": "textarea", "label": "Draw or tape here the leaf you liked best, and tell what it felt like to rub slowly:"}, {"id": "f1", "type": "textarea", "label": "Which leaf is a calm feeling, and which is a big feeling? Why?"}, {"id": "f2", "type": "textarea", "label": "What did your hands and breath do when you went slowly?"}, {"id": "f3", "type": "textarea", "label": "Grown-up: what I noticed about my child''s pace, and when they slowed down on their own:"}, {"id": "f4", "type": "textarea", "label": "Where will we hang the rubbings, and when could slow hands help this week?"}]'::jsonb, array['children', 'grounding', 'craft']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('muffin-tin-feelings-bean-toss-play', 'Muffin Tin Feelings Bean Toss Play', 'kids'::resource_kind, 'A bean toss game into a muffin tin where each cup is labeled with a feeling the child then talks about.', 'Use it to get a child naming feelings through tossing and aiming, with the parent taking turns.', array['Children']::text[], '20 minutes', 'Tape a feeling word or face into each cup of a muffin tin (happy, mad, worried, sad, excited, calm, and a wild card), stand back a few feet, and take turns tossing dried beans or pom-poms. Whichever cup the bean lands in, the tosser says a time they felt that way, in one sentence. The parent plays too and answers honestly about their own small feelings, which teaches the child that grown-ups have them. Watch for a child who will only toss and not talk; let them pass twice, then make the parent''s turn a model of a one-sentence answer.', '[{"id": "f0", "type": "textarea", "label": "Draw your muffin tin here with the feeling in each cup:"}, {"id": "f1", "type": "textarea", "label": "Which cup did your bean land in most? Tell about one time you felt that way:"}, {"id": "f2", "type": "textarea", "label": "Which feeling was easiest to talk about, and which was hardest?"}, {"id": "f3", "type": "textarea", "label": "Grown-up: a feeling I shared during the game, and how my child reacted:"}, {"id": "f4", "type": "textarea", "label": "What feeling would you add to the tin next time?"}]'::jsonb, array['children', 'emotion identification', 'play']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('tin-can-stilts-steady-steps-play', 'Tin Can Stilts Steady Steps Play', 'kids'::resource_kind, 'A balance play on tin can stilts where the child practices slow, steady steps and recovering from a wobble.', 'Use it to give a child a body lesson in steadiness and in getting back up after a wobble, with the parent spotting.', array['Children']::text[], '30 minutes to build, played over days', 'Two large empty cans with holes punched near the base and a loop of strong cord through each make a pair of stilts; the parent does the punching and checks for sharp edges. The child stands on the cans, holds the cords taut, and walks: it only works slowly, with attention, and everyone wobbles. The parent spots by walking alongside and names what the child does when they wobble (you stopped, you breathed, you tried again). Watch for a child who throws the stilts down at the first wobble; make the wobble the point, and count recoveries rather than steps.', '[{"id": "f0", "type": "textarea", "label": "Draw your stilts here and tell how many steps you took on your first try:"}, {"id": "f1", "type": "textarea", "label": "What did you do when you wobbled? Tell about the time you did not fall:"}, {"id": "f2", "type": "textarea", "label": "What helped you stay steady: slow steps, looking ahead, breathing?"}, {"id": "f3", "type": "textarea", "label": "Grown-up: what I noticed my child doing after a wobble, and what I said:"}, {"id": "f4", "type": "textarea", "label": "A time this week that felt like a wobble, and what a steady step would be:"}]'::jsonb, array['children', 'regulation', 'play']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('ribbon-wind-sock-breath-craft', 'Ribbon Wind Sock Breath Craft', 'kids'::resource_kind, 'A paper and ribbon wind sock the child makes and then blows through to see a long, slow breath.', 'Use it to give a child a breathing tool they built themselves and can see working.', array['Children']::text[], '25 minutes', 'The child decorates a strip of construction paper, rolls it into a tube the parent tapes, and tapes long ribbons or tissue strips along the bottom edge. Held up, a slow steady breath makes the ribbons stream out and stay out; a quick puff just flicks them. The child practices making the ribbons stream for as long as they can, counting, and the parent takes turns and loses on purpose sometimes. Watch for a child who gets dizzy competing on long breaths; switch to making the ribbons sway gently rather than stream hard.', '[{"id": "f0", "type": "textarea", "label": "Draw your wind sock here with its colors and ribbons:"}, {"id": "f1", "type": "textarea", "label": "How long could you make the ribbons stream? Count and write it:"}, {"id": "f2", "type": "textarea", "label": "What happens to the ribbons with a fast puff, and what happens with a slow breath?"}, {"id": "f3", "type": "textarea", "label": "Grown-up: when my child blew slowly, what I noticed in their face and shoulders:"}, {"id": "f4", "type": "textarea", "label": "Where will the wind sock hang, and when could a wind sock breath help this week?"}]'::jsonb, array['children', 'breathing', 'craft']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('shoebox-quiet-den-for-a-toy-craft', 'Shoebox Quiet Den for a Toy Craft', 'kids'::resource_kind, 'A craft where the child builds a tiny quiet den for a favorite toy and decides what makes a place feel calm.', 'Use it to help a child work out what a calm place needs by building one for a toy before making their own.', array['Children']::text[], '30 minutes', 'The child takes a shoebox, cuts a door with the parent''s help, and furnishes a den for a small toy: fabric scraps for a bed, a cotton ball pillow, a drawn window, a sign on the door. As they build, the parent asks what the toy needs in there to feel calm (soft things, dim light, quiet, a friend nearby) and writes the answers down. Then they look around the house for a corner where the child could have the same things. The den stays on a shelf as a reminder. Watch for a child who fills the den with action figures and noise; ask what the toy would want after a hard day, and build that side too.', '[{"id": "f0", "type": "textarea", "label": "Draw your toy''s den here and label what is inside:"}, {"id": "f1", "type": "textarea", "label": "What does your toy need in the den to feel calm? List everything:"}, {"id": "f2", "type": "textarea", "label": "Where in our house could you have a quiet den of your own, and what would go in it?"}, {"id": "f3", "type": "textarea", "label": "Grown-up: what my child said a calm place needs, in their words:"}, {"id": "f4", "type": "textarea", "label": "When would your toy go to its den, and when could you go to yours?"}]'::jsonb, array['children', 'self-soothing', 'craft']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('anonymous-worry-slip-guess-who-game', 'Anonymous Worry Slip Guess Who Game', 'game'::resource_kind, 'A group game where worries are written anonymously, read aloud, and the group guesses how many share each one.', 'Use it to show a group how common their private worries are, without anyone having to own one aloud.', array['Groups', 'Teens', 'Adults']::text[], '30 minutes', 'Everyone writes one current worry on an identical slip and folds it into a bowl. The leader reads each slip aloud; before anyone speaks, every member writes a guess at how many people in the room share that worry, then hands go up for those who do, and the guesses are compared to the count. Debrief: which worries turned out to be more common than guessed, and what it was like to see hands go up for your own slip. Watch for a slip that discloses risk; the leader holds it and follows up privately, and the group hears that 988 can be called or texted.', '[{"id": "f0", "type": "textarea", "label": "My worry slip, written for the bowl (no name):"}, {"id": "f1", "type": "textarea", "label": "The slip that surprised me most, and how many hands went up compared to my guess:"}, {"id": "f2", "type": "textarea", "label": "What it was like to see hands go up for my own slip:"}, {"id": "f3", "type": "textarea", "label": "Debrief: what this game tells me about how alone I am with my worries:"}, {"id": "f4", "type": "textarea", "label": "If a worry on a slip or in my head is about hurting myself: 988 (call or text) and the person I would tell:"}]'::jsonb, array['game', 'group', 'worry']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('lily-pad-hop-group-crossing-game', 'Lily Pad Hop Group Crossing Game', 'game'::resource_kind, 'A teamwork game where the group crosses a room on paper lily pads that vanish if nobody is touching them.', 'Use it to get a group planning, communicating and helping each other across, with a debrief on how they did it.', array['Groups', 'Teens', 'Children']::text[], '30 minutes', 'Lay paper plates (lily pads) in a bag; the group gets a few less than they have members. The goal is to get everyone from one wall to the other stepping only on pads; a pad nobody is touching is removed by the leader, and anyone who steps on the floor sends the whole group back to the start. The group must plan, pass pads forward, keep a foot or hand on each one and wait for each other. Debrief: who led, who waited, how the group handled a slip, and what changed in round two. Watch for one member being blamed for a reset; the rule is that the group goes back together.', '[{"id": "f0", "type": "textarea", "label": "Round one: how far we got, and why we had to go back:"}, {"id": "f1", "type": "textarea", "label": "Our plan for round two, in a few words:"}, {"id": "f2", "type": "textarea", "label": "Who led, who waited, and who helped someone across:"}, {"id": "f3", "type": "textarea", "label": "What our group did when someone slipped:"}, {"id": "f4", "type": "textarea", "label": "Debrief: one thing this game showed me about working with others:"}]'::jsonb, array['game', 'group', 'communication']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('sentence-auction-bid-on-unhelpful-thoughts-game', 'Sentence Auction Bid on Unhelpful Thoughts Game', 'game'::resource_kind, 'An auction game where teams spend play money bidding on thoughts, then learn which ones were worth buying.', 'Use it to get a group weighing which thoughts deserve attention and which are expensive to buy into.', array['Groups', 'Teens', 'Adults']::text[], '35 minutes', 'Each team gets the same budget of play money. The leader auctions off sentences one at a time, a mix of unhelpful thoughts (everyone is judging me, I always ruin things) and useful ones (I can ask for help, one bad hour is not a bad day). The catch, revealed at the end, is that unhelpful thoughts cost their price and give nothing back, while useful ones pay back double. Debrief: which sentences felt worth bidding on in the heat of the auction, and which ones the players buy into for free every day. Watch for teams that treat it as a joke; ask each to name one sentence they really do pay for.', '[{"id": "f0", "type": "textarea", "label": "The sentences our team bought, and what we paid for each:"}, {"id": "f1", "type": "textarea", "label": "The reveal: which of our purchases paid back and which cost us:"}, {"id": "f2", "type": "textarea", "label": "A sentence I bid hard on without noticing it was unhelpful:"}, {"id": "f3", "type": "textarea", "label": "One thought I buy into for free most days, and what it costs me:"}, {"id": "f4", "type": "textarea", "label": "Debrief: what I would bid on differently in real life this week:"}]'::jsonb, array['game', 'thinking traps', 'group']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('change-three-things-observation-partner-game', 'Change Three Things Observation Partner Game', 'game'::resource_kind, 'A partner game of noticing: turn away, change three small things, turn back, and spot the changes.', 'Use it to practice close attention to another person and to the present moment, in a quick, playful round.', array['Groups', 'Children', 'Teens']::text[], '20 minutes', 'Partners face each other for thirty seconds and look carefully. They turn back to back; each changes three small things (a rolled sleeve, a swapped ring, untied lace, hair tucked). They turn around and take turns naming the changes; a point for each one spotted. Three rounds, swapping partners once. Debrief: what did you notice in the first look that you usually would not, and what was it like to be looked at that closely. Watch for a member who is uncomfortable being examined; let them be the spotter only, or pair them with the leader.', '[{"id": "f0", "type": "textarea", "label": "Round one: the three things my partner changed, and how many I spotted:"}, {"id": "f1", "type": "textarea", "label": "What I noticed about my partner in the first look that I usually would not:"}, {"id": "f2", "type": "textarea", "label": "What it was like to be looked at that carefully:"}, {"id": "f3", "type": "textarea", "label": "The round where I was most present, and what helped:"}, {"id": "f4", "type": "textarea", "label": "Debrief: one place this week I could look this closely at what is in front of me:"}]'::jsonb, array['game', 'mindfulness', 'attention']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('pressure-cooker-steam-valve-toss-game', 'Pressure Cooker Steam Valve Toss Game', 'game'::resource_kind, 'A beanbag game where a growing pile of stressors builds pressure and each catch is a steam valve the player names.', 'Use it to get a group naming stressors and matching them with releases, with a debrief on what the valve does.', array['Groups', 'Teens', 'Adults']::text[], '30 minutes', 'The group stands in a circle around a bucket (the pressure cooker). On each turn a player names a stressor and drops a beanbag in; when the bucket holds five, the pressure is on, and the next player must name a release (a steam valve: a walk, a call, a shower, saying no) and toss one beanbag out of the bucket to a teammate, who must catch it and name a second release. A drop means the pressure stays. Debrief: which stressors came up most, which releases were named most, and which releases the players actually use. Watch for a release that is really avoidance.', '[{"id": "f0", "type": "textarea", "label": "The stressors I dropped into the cooker:"}, {"id": "f1", "type": "textarea", "label": "The releases I named when I tossed one out:"}, {"id": "f2", "type": "textarea", "label": "The releases other people named that I had not thought of:"}, {"id": "f3", "type": "textarea", "label": "Which of the releases on the list I actually use, and which I only name:"}, {"id": "f4", "type": "textarea", "label": "Debrief: one steam valve I will try this week when the pressure builds:"}]'::jsonb, array['game', 'group', 'stress']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('watching-the-news-after-a-disaster-pacing-sheet', 'Watching the News After a Disaster Pacing Sheet', 'worksheet'::resource_kind, 'A pacing sheet for a client whose own past gets stirred up by wall-to-wall coverage of a disaster or attack.', 'Use it to help a client decide how much news to take in, when, and how to steady themselves afterward.', array['Adults', 'Teens']::text[], '20 minutes, then used during the coverage', 'Coverage of a disaster can pull a client with their own history straight back into it, and most keep watching anyway. The sheet has the client set the amount (one check in the morning, one in the evening, headlines only or one trusted source), notice the signs that they have taken in too much (jumpy, numb, up at night), and plan what they do right after a check: a walk, a call, a chore with their hands. Keep the focus on today''s steadiness; the client''s own events are not the subject here. Watch for a client who frames watching as a duty to the people affected.', '[{"id": "f0", "type": "textarea", "label": "How much news I will take in each day, from which source, and when:"}, {"id": "f1", "type": "textarea", "label": "The signs that I have taken in too much, in my body and my sleep:"}, {"id": "f2", "type": "textarea", "label": "What I will do in the ten minutes right after a news check:"}, {"id": "f3", "type": "textarea", "label": "Who I will not discuss the coverage with, and what I will say if they bring it up:"}, {"id": "f4", "type": "textarea", "label": "One thing I can do for the people affected that is not watching:"}, {"id": "f5", "type": "textarea", "label": "At the end of the week: how the pacing went, and what I will change:"}]'::jsonb, array['PTSD and trauma', 'pacing', 'grounding']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('jumping-at-every-siren-means-i-am-weak-thought-check-sheet', 'Jumping at Every Siren Means I Am Weak Thought Check Sheet', 'cbt'::resource_kind, 'A thought check for the self-judgment that follows a startle response the client did not choose.', 'Use it to separate the startle itself, which the body does, from the verdict the client passes on themselves for it.', array['Adults', 'Teens']::text[], '20 minutes', 'A siren, a slammed door, a hand on the shoulder: the client jumps, and a second later tells themselves they are weak, broken or embarrassing. The sheet takes the moment apart in two layers: what the body did (which was fast and not chosen) and what the mind said about it. Then the client looks for evidence about the verdict: what they know about how bodies respond after hard things, what they would say to a friend who jumped, and what the startle actually cost them versus what the verdict cost. Watch for the client who accepts the body part but keeps the verdict.', '[{"id": "f0", "type": "textarea", "label": "The moment: what set off the startle, and what my body did in the first second:"}, {"id": "f1", "type": "textarea", "label": "The verdict my mind passed on me right after, in its own words:"}, {"id": "f2", "type": "textarea", "label": "What I know about how bodies react after hard things, and what I would say to a friend who jumped:"}, {"id": "f3", "type": "textarea", "label": "What the startle itself cost me, next to what the verdict cost me:"}, {"id": "f4", "type": "textarea", "label": "A balanced thought about the jump that I can stand behind:"}, {"id": "f5", "type": "textarea", "label": "How I will steady myself the next time, before the verdict arrives:"}]'::jsonb, array['PTSD and trauma', 'thinking traps', 'self-criticism']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('turning-the-volume-knob-down-not-off-page', 'Turning the Volume Knob Down Not Off Page', 'act'::resource_kind, 'An acceptance page that treats hard feelings as a sound the client can turn down and live beside, not switch off.', 'Use it to move a client away from the fight to make a feeling stop and toward living with it at a lower volume.', array['Adults', 'Teens']::text[], '15 minutes', 'Clients with a trauma history often have one goal for a feeling: off. The page offers a knob instead of a switch: the feeling has a volume, grounding and pacing turn it down, and the client can act while it plays quietly. The client names the feeling, rates its volume now, lists what turns it down a notch (feet on the floor, a cold drink, naming five things in the room, a call), and what they could do at a lower volume that they cannot do at full blast. Watch for a client who hears down as giving up.', '[{"id": "f0", "type": "textarea", "label": "The feeling that is loud right now, and its volume from 0 to 10:"}, {"id": "f1", "type": "textarea", "label": "What turns the volume down a notch for me, in the order I would try them:"}, {"id": "f2", "type": "textarea", "label": "What I could do at a volume of 4 that I cannot do at 9:"}, {"id": "f3", "type": "textarea", "label": "What the fight to switch the feeling off completely has cost me:"}, {"id": "f4", "type": "textarea", "label": "The sentence I will say to myself when the volume climbs:"}, {"id": "f5", "type": "textarea", "label": "This week: a time I turned it down a notch and did something anyway:"}]'::jsonb, array['PTSD and trauma', 'acceptance', 'grounding']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('self-soothe-with-a-warm-mug-in-both-hands-card', 'Self-Soothe With a Warm Mug in Both Hands Card', 'dbt'::resource_kind, 'A self-soothe card built around a warm mug held in both hands, using heat, smell and taste to settle the body.', 'Use it to give a client a self-soothing routine they can do in any kitchen in two minutes when the body is braced.', array['Adults', 'Teens']::text[], '5 minutes to prepare, two minutes to use', 'Self-soothing through the senses works best when it is simple and already in the house, and a warm drink is in most of them. The card has the client choose the drink and the mug, and walk through the senses one at a time: the heat in both palms, the steam on the face, the smell before the first sip, the taste, the sound of the kitchen. They note what they tend to do instead when braced (pace, scroll, go still) and rate the body before and after. Watch for a client who gulps the drink and moves on; the card is about the two minutes with the mug, not the drink.', '[{"id": "f0", "type": "textarea", "label": "The drink and the mug I will use, and where they live:"}, {"id": "f1", "type": "textarea", "label": "Touch: what I notice in my hands and face as I hold it:"}, {"id": "f2", "type": "textarea", "label": "Smell and taste: what I notice before and during the first sip:"}, {"id": "f3", "type": "textarea", "label": "Sound and sight: what I notice in the room while I hold it:"}, {"id": "f4", "type": "textarea", "label": "My body before the mug and after, 0 to 10, and what I usually do instead when braced:"}, {"id": "f5", "type": "textarea", "label": "A time this week I used it, and what happened next:"}]'::jsonb, array['PTSD and trauma', 'self-soothing', 'core DBT']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('calm-cave-blanket-fort-rules-play', 'Calm Cave Blanket Fort Rules Play', 'kids'::resource_kind, 'A blanket fort the child builds as a calm cave, with rules the child writes about who may come in and what happens inside.', 'Use it to give a child a safe place they built and control, and to practice asking for space and inviting it.', array['Children']::text[], '40 minutes', 'The child builds a blanket fort with the parent''s help (chairs, a sheet, cushions, a flashlight), then writes or draws the cave rules: who may come in, how you ask, what happens inside (quiet voices, soft things, a book), and the signal for wanting to be alone. The parent follows the rules every time, including knocking and waiting for the answer, which teaches the child that their space is honored. If a child discloses something while playing, listen, keep calm, and remember your reporting duties. Watch for a parent who enters without asking.', '[{"id": "f0", "type": "textarea", "label": "Draw your calm cave here with what is inside:"}, {"id": "f1", "type": "textarea", "label": "The cave rules: who can come in, how they ask, and what happens inside:"}, {"id": "f2", "type": "textarea", "label": "The signal that means I want to be alone, and the signal that means come in:"}, {"id": "f3", "type": "textarea", "label": "Grown-up: how I followed the rules, and what I noticed my child do in the cave:"}, {"id": "f4", "type": "textarea", "label": "Three calm things that live in the cave, and when I might go there this week:"}]'::jsonb, array['PTSD and trauma', 'children', 'safety']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('storm-warning-app-refresh-count-log-sheet', 'Storm Warning App Refresh Count Log Sheet', 'worksheet'::resource_kind, 'A log for the client who refreshes the weather app over and over before a storm, with a planned check schedule.', 'Use it to make the refreshing visible and replace it with a few planned checks the client can trust.', array['Adults', 'Teens']::text[], 'One week', 'A storm in the forecast turns some clients into meteorologists, refreshing every few minutes and feeling worse each time. The log has them tally refreshes for two days to get a baseline, then set a check schedule (morning, midday, evening, plus the official alert that will arrive on its own), and tally the urges they rode out. The sheet also asks what the client would do differently at check ten that they did not do at check one, which is usually nothing. Watch for a client who plans the checks and then adds just one more.', '[{"id": "f0", "type": "textarea", "label": "Baseline: how many times I refreshed the forecast on two ordinary storm days:"}, {"id": "f1", "type": "textarea", "label": "My check schedule: the times I will look, and the alerts that will come to me anyway:"}, {"id": "f2", "type": "textarea", "label": "The tally of refresh urges I rode out each day this week:"}, {"id": "f3", "type": "textarea", "label": "What I would do differently after check ten that I did not do after check one:"}, {"id": "f4", "type": "textarea", "label": "What I did with the time and attention I did not spend refreshing:"}, {"id": "f5", "type": "textarea", "label": "Other things I refresh the same way, and whether this schedule could work for them:"}]'::jsonb, array['anxiety', 'self-monitoring', 'uncertainty']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('prepare-for-every-question-or-freeze-rule-test-sheet', 'Prepare for Every Question or Freeze Rule Test Sheet', 'cbt'::resource_kind, 'A rule test for the belief that a client must prepare for every possible question or they will freeze.', 'Use it to test over-preparation against an experiment in going in with less, and to record what actually happened.', array['Adults', 'Teens']::text[], '25 minutes to set up, 10 minutes to debrief', 'The client spends hours scripting answers for a meeting, a date or a class discussion, and believes the scripting is what prevents freezing. The sheet states the rule, lists what it costs (sleep, hours, the stiffness of reading from a script), and sets up an experiment: a low-stakes situation where the client prepares three main points and no scripts, predicts how often they will freeze and for how long, and then records what happened. Watch for the client who picks a situation so trivial that nothing is tested; the sheet asks them to rate the stakes.', '[{"id": "f0", "type": "textarea", "label": "The rule, in my words: if I do not prepare for every question, then..."}, {"id": "f1", "type": "textarea", "label": "What following this rule costs me in a typical week:"}, {"id": "f2", "type": "textarea", "label": "The experiment: a situation (stakes 1 to 10), prepared with three points and no scripts:"}, {"id": "f3", "type": "textarea", "label": "My prediction: how many times I will freeze, and for how long:"}, {"id": "f4", "type": "textarea", "label": "What actually happened, including the questions I had not prepared for:"}, {"id": "f5", "type": "textarea", "label": "What the rule looks like now, and the next situation to test it in:"}]'::jsonb, array['anxiety', 'behavioral experiment', 'core beliefs']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('anxious-mind-as-an-overcautious-crossing-guard-page', 'Anxious Mind as an Overcautious Crossing Guard Page', 'act'::resource_kind, 'A defusion page that casts the anxious mind as a crossing guard who never lets anyone cross the empty street.', 'Use it to help a client thank the mind for watching the road and cross anyway when the street is clear.', array['Adults', 'Teens']::text[], '15 minutes', 'A crossing guard who stops traffic is useful; one who holds the sign up when the road is empty keeps everyone on the curb. The page has the client list the streets their mind will not let them cross (the phone call, the invitation, the question in the meeting), note what the guard says each time, and look at the actual traffic: how often has crossing gone badly? Then they practice the move: thanks for looking, and step off the curb. Watch for a client who argues with the guard about whether the road is clear; the practice is to look for themselves and go.', '[{"id": "f0", "type": "textarea", "label": "The streets my mind will not let me cross right now:"}, {"id": "f1", "type": "textarea", "label": "What the crossing guard says each time I step toward the curb:"}, {"id": "f2", "type": "textarea", "label": "The actual traffic: how often crossing has gone badly, and how badly:"}, {"id": "f3", "type": "textarea", "label": "The move: what I will say to the guard, and the step I will take:"}, {"id": "f4", "type": "textarea", "label": "One crossing I made this week, and what the guard said while I did it:"}, {"id": "f5", "type": "textarea", "label": "What the guard is good for, and when I do want it to stop me:"}]'::jsonb, array['anxiety', 'defusion', 'metaphor']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('cope-ahead-for-the-driving-test-card', 'Cope Ahead for the Driving Test Card', 'dbt'::resource_kind, 'A cope ahead card for a driving test, rehearsing the hard moments in imagination with the skills attached.', 'Use it to help a client walk through a test they dread, skill by skill, before the day so the plan is already in them.', array['Teens', 'Adults']::text[], '25 minutes', 'The driving test is a clean case: the examiner''s clipboard, the parallel park, the stall at the light. The card has the client write the moments they fear most, the skill for each (paced breathing at the stop sign, a describe statement for the clipboard, self-talk for a mistake), and then rehearse the whole test in their mind twice, including recovering from one error. Adult learners and retakers use it the same way. Watch for a rehearsal that only imagines things going well; the skill is in rehearsing the stumble and the recovery.', '[{"id": "f0", "type": "textarea", "label": "The test, in detail: where, who, and the moments I dread most:"}, {"id": "f1", "type": "textarea", "label": "The skill I will use at each dreaded moment:"}, {"id": "f2", "type": "textarea", "label": "The rehearsal: what I pictured, including one mistake and how I recovered:"}, {"id": "f3", "type": "textarea", "label": "What my body did during the rehearsal, and how I relaxed afterward:"}, {"id": "f4", "type": "textarea", "label": "The morning of the test: the first three things I will do:"}, {"id": "f5", "type": "textarea", "label": "After the test: what happened, and which rehearsed skill I actually used:"}]'::jsonb, array['anxiety', 'cope ahead', 'distress tolerance']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('spin-the-worry-then-spin-the-plan-game', 'Spin the Worry Then Spin the Plan Game', 'game'::resource_kind, 'A two-spinner game: one lands on a worry, the other on a coping move, and the player has to make them fit.', 'Use it to get a group pairing worries with plans fast, with a debrief on which pairs would actually work.', array['Groups', 'Teens', 'Adults']::text[], '30 minutes', 'Two paper spinners: one with worries the group wrote beforehand (the test, the text with no reply, the noise at night), one with plans (ask someone, write it down, wait an hour, do the next small thing, check the facts, breathe and carry on). On a turn the player spins both and has thirty seconds to say how that plan would work for that worry, or argue that it would not and pick a better one. Debrief which plans fit almost every worry and which worries had none. Watch for a worry that is a risk rather than a worry; take it aside and name 988 (call or text) for the group.', '[{"id": "f0", "type": "textarea", "label": "The worries our group put on the spinner:"}, {"id": "f1", "type": "textarea", "label": "The plans on the other spinner:"}, {"id": "f2", "type": "textarea", "label": "The pairing I had to argue for, and whether the group bought it:"}, {"id": "f3", "type": "textarea", "label": "The plan that fit almost every worry, and the worry no plan fit:"}, {"id": "f4", "type": "textarea", "label": "Debrief: one pairing I will use this week when the worry comes up:"}]'::jsonb, array['anxiety', 'game', 'coping skills']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('dishes-pile-one-plate-rule-sheet', 'Dishes Pile One Plate Rule Sheet', 'worksheet'::resource_kind, 'A one-plate rule for the sink that has become a monument to a low week, with a log of what one plate led to.', 'Use it to shrink a stalled chore to one plate a day and record what happens after the first one is done.', array['Adults', 'Teens']::text[], 'One week', 'A full sink is a common marker of a low stretch and a daily reminder of it. The rule is one plate: wash one item and the day''s chore is done, with permission to stop. The sheet logs each day''s plate, the time it took, what the client felt before and after, and whether they went on to a second item (they are allowed to, but not required to). The sink is the example; the sheet works for one email, one shirt folded, one bag of trash. Watch for the client who sets the rule at one plate and then judges themselves for not doing the whole sink; the rule is the whole point.', '[{"id": "f0", "type": "textarea", "label": "The chore that has stalled, and how long it has been building:"}, {"id": "f1", "type": "textarea", "label": "My one-item rule for this week, written as a sentence I agree with:"}, {"id": "f2", "type": "textarea", "label": "Each day: the item, how long it took, and how I felt before and after:"}, {"id": "f3", "type": "textarea", "label": "The days I went on to a second item, and what made that happen:"}, {"id": "f4", "type": "textarea", "label": "What the pile looked like at the end of the week:"}, {"id": "f5", "type": "textarea", "label": "Another stalled chore I could give a one-item rule:"}]'::jsonb, array['depression', 'behavioral activation', 'routines']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('nothing-will-feel-good-anyway-prediction-sheet', 'Nothing Will Feel Good Anyway Prediction Sheet', 'cbt'::resource_kind, 'A prediction sheet that tests the low-mood forecast that an activity will feel like nothing before it is tried.', 'Use it to put a number on the prediction, do the thing, and compare, so the forecast loses some of its authority.', array['Adults', 'Teens']::text[], '20 minutes plus the activity', 'Low mood makes confident forecasts: the walk will be pointless, the call will be draining, the show will not be funny. The sheet has the client write the planned activity, predict enjoyment and sense of accomplishment from 0 to 10, and name the thought behind the number. After the activity they rate the actual enjoyment and accomplishment and write what the forecast missed. Watch for the client who rates afterward from memory of the forecast rather than from the experience; ask them to rate during or right after.', '[{"id": "f0", "type": "textarea", "label": "The activity I am going to do, and when:"}, {"id": "f1", "type": "textarea", "label": "My forecast: enjoyment 0 to 10, accomplishment 0 to 10, and the thought behind the numbers:"}, {"id": "f2", "type": "textarea", "label": "The actual ratings, made during or right after:"}, {"id": "f3", "type": "textarea", "label": "What the forecast got wrong, and what it got right:"}, {"id": "f4", "type": "textarea", "label": "Three more forecasts and results from this week:"}, {"id": "f5", "type": "textarea", "label": "What I notice about how my forecasts run compared with what happens:"}]'::jsonb, array['depression', 'predictions', 'behavioral activation']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('low-mood-as-wet-sand-in-my-shoes-still-walking-page', 'Low Mood as Wet Sand in My Shoes Still Walking Page', 'act'::resource_kind, 'An acceptance page that pictures low mood as wet sand in the shoes: heavy, gritty and walkable.', 'Use it to help a client keep moving toward what matters with the heaviness present, instead of waiting for dry shoes.', array['Adults', 'Teens']::text[], '15 minutes', 'Wet sand in the shoes makes every step heavier and nobody enjoys it, but people walk home from the beach anyway. The page has the client describe the heaviness in their own words, name what they have been waiting to do until it passes, and pick one direction worth walking in with the sand still there. Then they write what a step looks like at this weight, smaller than usual, and the first one for this week. Watch for a client who hears this as being told to push through; the page is about choosing direction, with the step sized to the day.', '[{"id": "f0", "type": "textarea", "label": "The heaviness this week, described in my own words:"}, {"id": "f1", "type": "textarea", "label": "What I have been waiting to do until the heaviness passes:"}, {"id": "f2", "type": "textarea", "label": "The direction worth walking in even with the sand in my shoes:"}, {"id": "f3", "type": "textarea", "label": "What a step looks like at this weight, and the first one I will take this week:"}, {"id": "f4", "type": "textarea", "label": "What waiting for dry shoes has cost me so far:"}, {"id": "f5", "type": "textarea", "label": "After the step: what the sand did, and what I noticed about the walking:"}]'::jsonb, array['depression', 'acceptance', 'metaphor']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('build-mastery-with-one-cleared-counter-card', 'Build Mastery With One Cleared Counter Card', 'dbt'::resource_kind, 'A build mastery card using one cleared kitchen counter as the day''s small, visible accomplishment.', 'Use it to give a client in a low stretch a daily task that is finishable, visible and slightly hard.', array['Adults', 'Teens']::text[], 'Ten minutes a day for a week', 'Build mastery is about doing one thing a day that is a little hard and finishing it, and in a low stretch a cleared counter can be exactly that. The card has the client pick the surface (a counter, a nightstand, the car seat), decide what cleared means for them, and each day note the time it took, how hard it was, and the sense of mastery afterward. The surface stays the same all week so the client can see it staying clear or filling back up without judgment. Watch for a client who raises the bar mid-week to the whole kitchen; the task is the one surface, and the skill is in finishing it.', '[{"id": "f0", "type": "textarea", "label": "The surface I am choosing, and what cleared means for it:"}, {"id": "f1", "type": "textarea", "label": "Each day: the time it took, how hard it was (0 to 10), and my sense of mastery (0 to 10):"}, {"id": "f2", "type": "textarea", "label": "What I noticed when I walked past the cleared surface later in the day:"}, {"id": "f3", "type": "textarea", "label": "The day it was hardest, and what got me to do it anyway:"}, {"id": "f4", "type": "textarea", "label": "What the surface looked like at the end of the week:"}, {"id": "f5", "type": "textarea", "label": "The next small surface, or the same one for another week:"}]'::jsonb, array['depression', 'build mastery', 'core DBT']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('low-week-signals-and-responses-card-for-partners', 'Low Week Signals and Responses Card for Partners', 'couples'::resource_kind, 'A shared card where one partner lists the signs that a low week is starting and the other lists what they will do.', 'Use it to give partners an agreed response to the early signs of a low stretch, so neither has to guess.', array['Couples']::text[], '30 minutes', 'When one partner''s mood drops, the other often notices before it is named and does not know whether to say so. The card has the partner who has low weeks list their early signals (sleeping later, going quiet at dinner, canceling plans, the dishes), and the responses they would actually want to each one: say something, say nothing, make the plan anyway, sit with me. The other partner writes what they tend to do now and what they will try instead. Watch for a wanted response that is really a request to be left alone for weeks; the card asks for a check-in point even then.', '[{"id": "f0", "type": "textarea", "label": "Partner with low weeks: my early signals, the ones you would see first:"}, {"id": "f1", "type": "textarea", "label": "For each signal: what I would want you to do, and what I would not want:"}, {"id": "f2", "type": "textarea", "label": "Other partner: what I tend to do now when I notice, and what I will try instead:"}, {"id": "f3", "type": "textarea", "label": "Together: the words either of us can use to name a low week starting:"}, {"id": "f4", "type": "textarea", "label": "The check-in point if the low week stretches on, and who we would call in:"}, {"id": "f5", "type": "textarea", "label": "After the next low week: which responses helped, and what we would change:"}]'::jsonb, array['depression', 'couples', 'support']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('long-text-message-reply-breakdown-sheet', 'Long Text Message Reply Breakdown Sheet', 'worksheet'::resource_kind, 'A sheet for the long message that sits unanswered for days, breaking the reply into parts the client can send.', 'Use it to get a stalled reply to a long message written and sent in pieces instead of waiting for the perfect whole.', array['Adults', 'Teens']::text[], '20 minutes', 'A long message from a friend or relative can sit unanswered for a week because answering it all feels like an essay, and the longer it sits, the worse it gets. The sheet has the client paste or summarize the message, list the separate things in it (a question, news, a request, a feeling), and write a one-line reply to each. Then they decide what to send now, even if it is only the first line and a note that more is coming. Watch for the client who wants to answer everything in one perfect message; the point is to send something today.', '[{"id": "f0", "type": "textarea", "label": "The message, in summary, and how long it has been sitting:"}, {"id": "f1", "type": "textarea", "label": "The separate things in it: questions, news, requests, feelings:"}, {"id": "f2", "type": "textarea", "label": "A one-line reply to each piece:"}, {"id": "f3", "type": "textarea", "label": "What I will send right now, even if it is only part of it:"}, {"id": "f4", "type": "textarea", "label": "What the delay may have said to them, and one sentence that addresses that:"}, {"id": "f5", "type": "textarea", "label": "Other messages sitting unanswered, and which one gets this next:"}]'::jsonb, array['ADHD', 'communication', 'avoidance']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('i-am-just-lazy-labeling-check-sheet', 'I Am Just Lazy Labeling Check Sheet', 'cbt'::resource_kind, 'A labeling check for the client who explains every unfinished task with one word about their character.', 'Use it to swap a global label for a specific description of what happened, and to see what the description suggests.', array['Adults', 'Teens']::text[], '20 minutes', 'Lazy is a label many clients with attention difficulties have carried since school, and it explains nothing while costing a great deal. The sheet takes one recent unfinished task and asks what actually happened, step by step: when did the client intend to do it, what pulled them off, what was missing (a start cue, a clear first step, a deadline that felt real). Then they look at the evidence against the label: the things they do finish, and what those have in common. Watch for a client who swaps lazy for another label such as hopeless; the move is from label to description.', '[{"id": "f0", "type": "textarea", "label": "The task I did not finish, and the label I gave myself for it:"}, {"id": "f1", "type": "textarea", "label": "What actually happened, step by step, from the intention to the moment it stalled:"}, {"id": "f2", "type": "textarea", "label": "What was missing: a start cue, a first step, a real deadline, something else:"}, {"id": "f3", "type": "textarea", "label": "Evidence against the label: things I do finish, and what they have in common:"}, {"id": "f4", "type": "textarea", "label": "A specific description of what happened instead of the label:"}, {"id": "f5", "type": "textarea", "label": "One change the description suggests for next time:"}]'::jsonb, array['ADHD', 'thinking traps', 'self-criticism']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('bored-in-the-middle-of-the-project-willingness-page', 'Bored in the Middle of the Project Willingness Page', 'act'::resource_kind, 'A willingness page for the moment a project stops being new and the mind looks for the exit.', 'Use it to help a client sit with the boredom of the middle and keep going toward what the project is for.', array['Adults', 'Teens']::text[], '15 minutes', 'Many clients start well and leave when the project gets dull, which is usually about a third of the way in. The page has the client name the project and what it is for, describe the boredom as it actually feels in the body and the mind, and list what the mind offers instead (a new idea, a reorganization, a snack). Then they rate their willingness to work bored for twenty minutes and set a timer. Afterward they record what happened to the boredom and the work. Watch for a client who swaps projects as the solution; the page asks what the last three middles led to.', '[{"id": "f0", "type": "textarea", "label": "The project, and what it is for in my life:"}, {"id": "f1", "type": "textarea", "label": "The boredom, as it actually feels in my body and what my mind says during it:"}, {"id": "f2", "type": "textarea", "label": "What my mind offers instead of the work when the middle arrives:"}, {"id": "f3", "type": "textarea", "label": "My willingness to work bored for twenty minutes, 0 to 10, and the timer I set:"}, {"id": "f4", "type": "textarea", "label": "What happened to the boredom and the work during the twenty minutes:"}, {"id": "f5", "type": "textarea", "label": "What the last three middles I left led to, and what this one could lead to:"}]'::jsonb, array['ADHD', 'willingness', 'committed action']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('pros-and-cons-of-pulling-an-all-nighter-grid', 'Pros and Cons of Pulling an All-Nighter Grid', 'dbt'::resource_kind, 'A pros and cons grid for the all-nighter, filled in before the night rather than at 2 a.m.', 'Use it to help a client weigh the all-nighter against a planned stop while they can still think clearly.', array['Teens', 'Adults']::text[], '20 minutes, done in the afternoon', 'The all-nighter looks like a solution at 11 p.m. and like a mistake at 3 p.m. the next day. The grid has the client fill in four cells in the afternoon: pros of pushing through, cons of pushing through, pros of stopping at a set time, cons of stopping, with the short-term and long-term versions of each. Then they set the stop time and what they will do at it (bed, or a planned early start). Watch for the client who fills in the pros of pushing through with real deadlines and the cons with vague ones; ask for what the last all-nighter actually produced.', '[{"id": "f0", "type": "textarea", "label": "Pros of pushing through all night, short term and long term:"}, {"id": "f1", "type": "textarea", "label": "Cons of pushing through, short term and long term, including what the last one produced:"}, {"id": "f2", "type": "textarea", "label": "Pros of stopping at a set time and starting early:"}, {"id": "f3", "type": "textarea", "label": "Cons of stopping:"}, {"id": "f4", "type": "textarea", "label": "The stop time I am setting, and what I will do when it arrives:"}, {"id": "f5", "type": "textarea", "label": "The next day: what I actually did, and how the morning went:"}]'::jsonb, array['ADHD', 'pros and cons', 'sleep']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('lost-item-detective-kit-craft', 'Lost Item Detective Kit Craft', 'kids'::resource_kind, 'A detective kit the child builds for finding lost things, with a magnifying glass and a search plan card.', 'Use it to turn the daily hunt for lost shoes and homework into a game with steps, led by the child.', array['Children']::text[], '30 minutes to build, used daily', 'The child decorates a small box or pouch as a detective kit: a toy magnifying glass, a notebook, a pencil, and a search plan card the child writes with the parent (last place I had it, retrace my steps, check the three usual spots, ask a witness). When something is lost, the child gets the kit and runs the plan instead of the parent running around the house. The parent plays the witness and answers questions, but does not lead. Watch for a parent who takes over at the first sign of frustration; let the plan card do the leading and the child do the finding.', '[{"id": "f0", "type": "textarea", "label": "Draw your detective kit here and what is inside it:"}, {"id": "f1", "type": "textarea", "label": "My search plan card: the steps I follow when something is lost:"}, {"id": "f2", "type": "textarea", "label": "The three usual spots where my things turn up:"}, {"id": "f3", "type": "textarea", "label": "Grown-up: a case my child solved with the kit, and what I did as the witness:"}, {"id": "f4", "type": "textarea", "label": "What would make the next case easier before it starts (a home for shoes, a hook for the backpack)?"}]'::jsonb, array['ADHD', 'children', 'craft']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('friday-afternoon-quitting-time-urge-plan-sheet', 'Friday Afternoon Quitting Time Urge Plan Sheet', 'worksheet'::resource_kind, 'A plan for the urge that arrives with the end of the work week, mapping the hours from quitting time to bed.', 'Use it to fill the Friday evening gap that substance use used to fill, hour by hour, before Friday comes.', array['Adults']::text[], '25 minutes, before Friday', 'For many clients the strongest urges arrive at the same time every week: Friday afternoon, when work ends and the old reward used to start. The sheet maps Friday from quitting time to bed in hour blocks and asks what substance use used to do in each (mark the end of work, loosen the shoulders, get them to the bar where the friends are), then what will do that job this Friday instead. Watch for a plan that is only avoidance; each hour needs something in it, not just something kept out.', '[{"id": "f0", "type": "textarea", "label": "Friday from quitting time to bed in hour blocks, and what substance use used to do in each hour:"}, {"id": "f1", "type": "textarea", "label": "What will do that job this Friday instead, hour by hour:"}, {"id": "f2", "type": "textarea", "label": "Who I will be with, and the place I will not go:"}, {"id": "f3", "type": "textarea", "label": "The hour I expect the urge to be strongest, and the person I will text then:"}, {"id": "f4", "type": "textarea", "label": "What I will tell myself if the urge says just this once:"}, {"id": "f5", "type": "textarea", "label": "Saturday morning: what happened, and what I will change for next Friday:"}]'::jsonb, array['addiction', 'urges', 'planning']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('one-weekend-off-will-not-count-thought-record', 'One Weekend Off Will Not Count Thought Record', 'cbt'::resource_kind, 'A thought record for the permission-giving thought that one weekend of substance use will not count.', 'Use it to catch the bargain the mind offers before a weekend and look at what past bargains actually led to.', array['Adults']::text[], '20 minutes', 'The thought arrives politely: one weekend off the plan, nobody will know, Monday it all goes back to normal. The record has the client write the situation, the thought and the belief in it, the feelings, and then the evidence: what the last one weekend led to, how many Mondays went back to normal, and what the client gains if the bargain is refused. A balanced thought follows, along with a plan for the weekend in question. Watch for the client who treats the record as a debate to win; it is a record of what the mind offers and what has followed.', '[{"id": "f0", "type": "textarea", "label": "The situation, and the bargain my mind offered, in its exact words:"}, {"id": "f1", "type": "textarea", "label": "How much I believed it (0 to 100), and what I felt:"}, {"id": "f2", "type": "textarea", "label": "Evidence for the bargain: times a weekend off really did not count:"}, {"id": "f3", "type": "textarea", "label": "Evidence against it: what past weekends off led to, and how many Mondays went back to normal:"}, {"id": "f4", "type": "textarea", "label": "A balanced thought I can carry into the weekend:"}, {"id": "f5", "type": "textarea", "label": "My plan for this weekend, and who knows about it:"}]'::jsonb, array['addiction', 'thought record', 'urges']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('minds-old-friend-who-only-calls-for-a-drink-page', 'Mind''s Old Friend Who Only Calls for a Drink Page', 'act'::resource_kind, 'A defusion page that casts the urge as an old friend who only ever calls with one invitation.', 'Use it to help a client recognize the urge''s voice, let the call ring, and choose what to do with the evening instead.', array['Adults']::text[], '15 minutes', 'Everyone knows the friend who only calls when they want company for one thing. The page has the client describe the urge as that caller: the time it calls, the tone, the lines it uses (you have had a hard week, everyone else is), and what it never asks about. Then they practice letting the call ring: noticing it, naming it (there is the call), and choosing the evening they want instead. Watch for a client who treats not answering as rudeness; the friend will call again regardless.', '[{"id": "f0", "type": "textarea", "label": "When the old friend usually calls, and the tone of the call:"}, {"id": "f1", "type": "textarea", "label": "The lines it uses to get me to say yes:"}, {"id": "f2", "type": "textarea", "label": "What it never asks about in my life:"}, {"id": "f3", "type": "textarea", "label": "Letting it ring: how I will notice and name the call this week:"}, {"id": "f4", "type": "textarea", "label": "The evening I want instead, and the first thing I will do when the phone rings:"}, {"id": "f5", "type": "textarea", "label": "If I picked up, what I would actually say to this friend:"}]'::jsonb, array['addiction', 'defusion', 'metaphor']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('pros-and-cons-of-using-after-the-promotion-party-grid', 'Pros and Cons of Using After the Promotion Party Grid', 'dbt'::resource_kind, 'A pros and cons grid for a celebration where substance use feels earned, filled in before the party.', 'Use it to help a client weigh the celebratory urge in advance, with the long-term column written in daylight.', array['Adults']::text[], '20 minutes, before the event', 'A promotion, a birthday, a finished project: celebration is one of the strongest cues for substance use because it comes with a sense of having earned it. The grid has four cells: pros of using at the party, cons of using, pros of not using, cons of not using, each with a short-term and a long-term line. The client fills it in before the event and names what celebration will look like without substance use (the toast with something else, leaving early for a good dinner, the call to the person who will be proud). Watch for a long-term column left thin; that is where the grid earns its keep.', '[{"id": "f0", "type": "textarea", "label": "Pros of using at the celebration, short term and long term:"}, {"id": "f1", "type": "textarea", "label": "Cons of using, short term and long term:"}, {"id": "f2", "type": "textarea", "label": "Pros of not using, short term and long term:"}, {"id": "f3", "type": "textarea", "label": "Cons of not using:"}, {"id": "f4", "type": "textarea", "label": "What celebrating will look like for me without substance use:"}, {"id": "f5", "type": "textarea", "label": "After the event: what I did, and what the grid got right:"}]'::jsonb, array['addiction', 'pros and cons', 'urges']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('substance-free-celebration-rituals-sheet-for-partners', 'Substance-Free Celebration Rituals Sheet for Partners', 'couples'::resource_kind, 'A sheet where partners design how they will mark good news and milestones without substance use at the center.', 'Use it to help a couple build celebrations that feel like celebrations, now that the old one is off the table.', array['Couples']::text[], '30 minutes', 'When one partner stops substance use, the couple often loses the way they celebrated, and good news starts to feel flat. The sheet has each partner list what the old celebrations gave them (the ritual, the marking of a moment, the loosening), then brainstorm new ones that give the same thing: a particular restaurant, a drive to the water, a dessert made at home, a toast with something they both like. The other partner writes what they will do about their own drinking then. Watch for a list that is only the old celebration minus the substance; it needs something added.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what our old celebrations gave me, and what I miss about them:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what our old celebrations gave me, and what I miss about them:"}, {"id": "f2", "type": "textarea", "label": "Together: new rituals that give us the same things, as many as we can think of:"}, {"id": "f3", "type": "textarea", "label": "The three we are choosing, and which kind of good news each one marks:"}, {"id": "f4", "type": "textarea", "label": "Partner not in recovery: what I will do about my own substance use at these moments:"}, {"id": "f5", "type": "textarea", "label": "The next thing worth celebrating, and the ritual we will use for it:"}]'::jsonb, array['addiction', 'couples', 'substance use']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('traffic-merge-lane-anger-log-sheet', 'Traffic Merge Lane Anger Log Sheet', 'worksheet'::resource_kind, 'A log of anger at the merge lane and other driving moments, tracking the trigger, the heat and what the client did.', 'Use it to make driving anger visible over a week and to find the two or three moments that account for most of it.', array['Adults', 'Teens']::text[], 'One week', 'Driving is where many clients lose their temper most often and most safely hidden, and the merge lane is the classic case. The log has the client note each flare for a week: the trigger (the late merger, the tailgater, the slow left lane), the heat from 0 to 10, what they did (horn, gesture, speeding up, muttering), and how long it stayed with them after the drive. At the end they find the top three triggers and write one different response for each, to try the next week. Watch for a client who logs only the other drivers'' behavior and not their own.', '[{"id": "f0", "type": "textarea", "label": "Each flare this week: the trigger, the heat (0 to 10), what I did, and how long it stayed with me:"}, {"id": "f1", "type": "textarea", "label": "My top three driving triggers by frequency or heat:"}, {"id": "f2", "type": "textarea", "label": "What each of the top three costs me, on the road and after:"}, {"id": "f3", "type": "textarea", "label": "One different response for each, to try next week:"}, {"id": "f4", "type": "textarea", "label": "What I will tell myself at the merge lane when the late merger appears:"}, {"id": "f5", "type": "textarea", "label": "Next week: the flares, and whether the new responses got used:"}]'::jsonb, array['anger management', 'self-monitoring', 'triggers']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('they-ignored-my-text-to-punish-me-thought-record', 'They Ignored My Text to Punish Me Thought Record', 'cbt'::resource_kind, 'A thought record for the anger that follows an unanswered text, when the silence is read as deliberate.', 'Use it to catch the mind-reading behind anger at an unanswered message and weigh it against the plain alternatives.', array['Adults', 'Teens']::text[], '20 minutes', 'An unanswered text becomes a deliberate act in the client''s mind within an hour, and the anger that follows is aimed at an intention nobody has confirmed. The record has the client write the message and the silence, the thought (they saw it and are making a point), the belief in it, and the anger from 0 to 100. Then the alternatives: phone in a bag, a meeting, a reply they are composing, a message that never arrived. Watch for a client who has sent a second, sharper message before the record is done; the sheet asks them to write that message out and consider whether it matched the facts.', '[{"id": "f0", "type": "textarea", "label": "The message I sent, when, and how long the silence has lasted:"}, {"id": "f1", "type": "textarea", "label": "The thought about why they have not replied, in its own words, and my belief in it:"}, {"id": "f2", "type": "textarea", "label": "My anger (0 to 100), and what I have done so far:"}, {"id": "f3", "type": "textarea", "label": "Plain alternatives for the silence, as many as I can list:"}, {"id": "f4", "type": "textarea", "label": "A balanced thought about the silence that fits the facts I actually have:"}, {"id": "f5", "type": "textarea", "label": "What I will do now: wait, send one neutral line, or call:"}]'::jsonb, array['anger management', 'thought record', 'mind reading']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('anger-as-a-fire-alarm-not-a-firefighter-page', 'Anger as a Fire Alarm Not a Firefighter Page', 'act'::resource_kind, 'An ACT page that separates anger''s job of sounding the alarm from the job of putting the fire out.', 'Use it to help a client hear anger as information and then choose the response by values rather than by heat.', array['Adults', 'Teens']::text[], '15 minutes', 'A fire alarm is useful: it tells you something is wrong and makes it impossible to ignore. The page has the client write what their anger was alarming about this week (a boundary crossed, unfairness, being unheard), what they did while the alarm was sounding, and whether that action put anything out. Then they name the firefighter: the response that would actually address what the alarm was about, chosen from what they care about. The last prompt is a plan for the next alarm. Watch for a client who wants the alarm disconnected; the page keeps the alarm and changes the response.', '[{"id": "f0", "type": "textarea", "label": "What my anger was alarming about this week, as specifically as I can say it:"}, {"id": "f1", "type": "textarea", "label": "What I did while the alarm was sounding:"}, {"id": "f2", "type": "textarea", "label": "Whether that put anything out, or just added noise:"}, {"id": "f3", "type": "textarea", "label": "The firefighter: the response that would actually address what the alarm was about:"}, {"id": "f4", "type": "textarea", "label": "What I care about that the firefighter would be protecting:"}, {"id": "f5", "type": "textarea", "label": "My plan for the next time the alarm sounds: listen, then do what?"}]'::jsonb, array['anger management', 'values', 'metaphor']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('opposite-action-to-going-cold-and-silent-card', 'Opposite Action to Going Cold and Silent Card', 'dbt'::resource_kind, 'An opposite action card for anger that goes cold and silent for days, with the steps back toward speaking.', 'Use it to help a client who withdraws into silence when angry act opposite to the urge and reopen the conversation.', array['Adults', 'Teens']::text[], '15 minutes', 'Not all anger is loud; for some clients it becomes a silence that can last days and punishes everyone in the house. Opposite action asks whether the anger fits the facts and whether acting on it is effective, and if not, to do the opposite all the way: approach rather than withdraw, soften the face and voice, and say one true sentence about what is wrong. The card has the client describe their silence, check the facts, and script the one sentence and the moment they will say it. Watch for a client who confuses this with pretending nothing happened; the sentence names the problem, gently.', '[{"id": "f0", "type": "textarea", "label": "What my going cold and silent looks like, and how long it usually lasts:"}, {"id": "f1", "type": "textarea", "label": "The anger underneath this time: does it fit the facts, and is the silence working?"}, {"id": "f2", "type": "textarea", "label": "Opposite action all the way: how I will approach, what my face and voice will do:"}, {"id": "f3", "type": "textarea", "label": "The one true sentence I will say about what is wrong:"}, {"id": "f4", "type": "textarea", "label": "When and where I will say it:"}, {"id": "f5", "type": "textarea", "label": "Afterward: what happened, and how the silence would have gone instead:"}]'::jsonb, array['anger management', 'opposite action', 'core DBT']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('pressure-valve-pass-the-balloon-game', 'Pressure Valve Pass the Balloon Game', 'game'::resource_kind, 'A group game where a balloon inflates with each named provocation and a player must release air with a cool-down move.', 'Use it to make the build-up of anger visible and to get a group practicing early release moves, with a debrief.', array['Groups', 'Teens', 'Children']::text[], '25 minutes', 'The leader holds a balloon. Going around the circle, each player names something that makes them angry and the leader adds a puff of air. When the balloon is clearly tight, the next player must name a cool-down move they would really use (step outside, count down from twenty, cold water on the wrists, say I need a minute) and the leader lets a little air out. Debrief: at what point did people start wanting to release air, and what does that point feel like in a body. Watch for cool-down moves that are really revenge.', '[{"id": "f0", "type": "textarea", "label": "The things that added air to the balloon in our round:"}, {"id": "f1", "type": "textarea", "label": "The cool-down moves people named, and the ones I would actually use:"}, {"id": "f2", "type": "textarea", "label": "The point when I started wanting to let air out, and what that feels like in my body:"}, {"id": "f3", "type": "textarea", "label": "If our balloon popped: what that is like in real life:"}, {"id": "f4", "type": "textarea", "label": "Debrief: the one early release move I will try this week:"}]'::jsonb, array['anger management', 'game', 'regulation']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('stove-knob-photo-reassurance-log-sheet', 'Stove Knob Photo Reassurance Log Sheet', 'worksheet'::resource_kind, 'A log for the client who photographs the stove, the lock or the iron before leaving, with a plan to leave the phone in the pocket.', 'Use it to make the photo-checking habit visible and to step down from it one leaving at a time.', array['Adults', 'Teens']::text[], 'One week', 'Photographing the stove before leaving feels like a clever fix and quietly becomes one more check: the client looks at the photo on the train, then wonders if the photo is from today. The log has the client record each leaving for a week: what they photographed, how many times they looked at the photos later, and the doubt from 0 to 10 after looking. Watch for the client who replaces the photo with a verbal check or a text to a partner; the sheet asks for all the forms the reassurance takes.', '[{"id": "f0", "type": "textarea", "label": "Each leaving this week: what I photographed, and how many times I looked at the photos later:"}, {"id": "f1", "type": "textarea", "label": "The doubt from 0 to 10 right after looking at a photo, and an hour later:"}, {"id": "f2", "type": "textarea", "label": "The one leaving a day I will do without the photo, and the doubt at the door:"}, {"id": "f3", "type": "textarea", "label": "What the doubt did over the next hour without the photo:"}, {"id": "f4", "type": "textarea", "label": "Other forms my reassurance takes: texting someone, saying it aloud, going back:"}, {"id": "f5", "type": "textarea", "label": "Next week''s plan: how many photo-free leavings, and what I will do with the doubt:"}]'::jsonb, array['OCD', 'self-monitoring', 'exposure']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('thinking-it-makes-it-more-likely-belief-check-sheet', 'Thinking It Makes It More Likely Belief Check Sheet', 'cbt'::resource_kind, 'A belief check for the idea that having a thought about something bad makes that thing more likely to happen.', 'Use it to put the thought-makes-it-happen belief on paper and test it against what the client already knows.', array['Adults', 'Teens']::text[], '25 minutes', 'Many clients with intrusive thoughts hold a quiet rule that thinking of a harm raises its odds, and so every thought must be neutralized. The sheet states the belief and the client''s confidence in it, then asks them to look at it: the harms they have thought about that never happened, the good things they have thought about that did not happen either, and what they would conclude if a friend said their thoughts steered the world. Watch for a client who agrees the belief is untrue but still neutralizes; name that gap and let it be the next piece of work.', '[{"id": "f0", "type": "textarea", "label": "The belief, in my words, and how much I hold it (0 to 100):"}, {"id": "f1", "type": "textarea", "label": "Harms I have thought about that never happened:"}, {"id": "f2", "type": "textarea", "label": "Good things I have thought about hard that did not happen either:"}, {"id": "f3", "type": "textarea", "label": "What I would say to a friend who told me their thoughts steer events:"}, {"id": "f4", "type": "textarea", "label": "The experiment: the trivial thing I thought about on purpose, and what happened:"}, {"id": "f5", "type": "textarea", "label": "My confidence in the belief now, and the gap between what I know and what I still do:"}]'::jsonb, array['OCD', 'core beliefs', 'behavioral experiment']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('intrusive-thought-as-a-wrong-number-call-page', 'Intrusive Thought as a Wrong Number Call Page', 'act'::resource_kind, 'A defusion page that treats an intrusive thought as a wrong number: it rang, it was not for you, you can hang up.', 'Use it to help a client let an intrusive thought be a misdial rather than a message that needs answering.', array['Adults', 'Teens']::text[], '15 minutes', 'A wrong number is startling for a second and then obviously not about you; you do not call back to make sure. The page has the client describe the intrusive thoughts that ring most often, what they currently do when one rings (answer, argue, check, call back with a ritual), and what it would look like to say wrong number and put the phone down. They practice on three calls this week and record what the thought did when nobody picked up. Watch for a client who treats hanging up as suppression; the phone can ring again and still be a wrong number.', '[{"id": "f0", "type": "textarea", "label": "The intrusive thoughts that ring most often, named briefly:"}, {"id": "f1", "type": "textarea", "label": "What I do now when one rings: answer, argue, check, call back:"}, {"id": "f2", "type": "textarea", "label": "What saying wrong number and putting the phone down would look like for me:"}, {"id": "f3", "type": "textarea", "label": "Three calls this week I did not pick up, and what the thought did:"}, {"id": "f4", "type": "textarea", "label": "What I have been doing while on the phone with these calls that I would rather be doing:"}, {"id": "f5", "type": "textarea", "label": "The sentence I will use the next time it rings:"}]'::jsonb, array['OCD', 'defusion', 'metaphor']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('willing-hands-when-the-urge-to-wash-comes-card', 'Willing Hands When the Urge to Wash Comes Card', 'dbt'::resource_kind, 'A willing hands card for the moment the urge to wash arrives, pairing an open posture with letting the urge be there.', 'Use it to give a client a bodily stance for riding out a washing urge without fighting it or obeying it.', array['Adults', 'Teens']::text[], '10 minutes to learn, used in the moment', 'Willing hands is a simple posture: hands open, palms up, fingers relaxed, on the lap or at the sides. For a client whose urges go to the sink, the posture is a direct opposite to the clenched, reaching hands of the urge. The card has the client describe their urge in the body, practice willing hands for two minutes in session while thinking about a usual trigger, and plan where they will use it (the kitchen, after the door handle, before bed). Watch for a client who uses the posture as a new ritual that must be done exactly; it is a stance, not a rule.', '[{"id": "f0", "type": "textarea", "label": "What the urge to wash feels like in my hands and arms:"}, {"id": "f1", "type": "textarea", "label": "Where I will use willing hands: the places and moments the urge usually comes:"}, {"id": "f2", "type": "textarea", "label": "The practice in session: the urge before (0 to 10) and after two minutes of the posture:"}, {"id": "f3", "type": "textarea", "label": "What my mind said while my hands were open:"}, {"id": "f4", "type": "textarea", "label": "Three times this week I used it, and what the urge did:"}, {"id": "f5", "type": "textarea", "label": "What I did next instead of going to the sink:"}]'::jsonb, array['OCD', 'willing hands', 'distress tolerance']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('germ-monster-shrink-ray-drawing-craft', 'Germ Monster Shrink Ray Drawing Craft', 'kids'::resource_kind, 'A drawing craft where the child draws the germ monster at full size and then redraws it smaller after each brave step.', 'Use it to give a child a way to picture the worry about germs and watch it shrink as they practice.', array['Children']::text[], '30 minutes to start, redrawn over weeks', 'The child draws the germ monster as big and scary as it feels, names it, and gives it a voice (what it says when they touch the door handle). The parent draws a shrink ray next to it. Each time the child does a brave step the family has agreed on with the clinician (touching the handle and waiting before washing, sharing a crayon), they redraw the monster a little smaller and the ray a little bigger. The parent cheers the brave step, not the clean hands. Watch for a parent who asks about germs afterward; the family rule is that the monster does not get interviews.', '[{"id": "f0", "type": "textarea", "label": "Draw your germ monster here as big as it feels, and give it a name:"}, {"id": "f1", "type": "textarea", "label": "What does the monster say to you? Write its bossy words:"}, {"id": "f2", "type": "textarea", "label": "The brave step I did, and the smaller monster I drew after:"}, {"id": "f3", "type": "textarea", "label": "Grown-up: the brave steps we agreed on, and what I said after each one:"}, {"id": "f4", "type": "textarea", "label": "What will the monster look like when the shrink ray is finished?"}]'::jsonb, array['OCD', 'children', 'craft']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('standing-in-the-long-airport-security-line-plan-sheet', 'Standing in the Long Airport Security Line Plan Sheet', 'worksheet'::resource_kind, 'A plan for the security line, where a client cannot leave, cannot sit and cannot hurry, and panic likes to arrive.', 'Use it to prepare a client for the one part of travel they cannot escape, with the sensations and the plan written down.', array['Adults', 'Teens']::text[], '25 minutes before the trip', 'The security line has everything a surge feeds on: no exit, no seat, strangers close by, a clock ticking. The sheet has the client write the sensations they expect, the thought that goes with each (I will faint, I will have to run and lose my place), and what they will actually do: feet planted, a slow exhale, eyes on one fixed point, a sentence for the stranger behind them if they need to step aside. Watch for a client who plans to avoid flying rather than plan the line; the sheet is for the line.', '[{"id": "f0", "type": "textarea", "label": "The sensations I expect in the line, and the thought that comes with each:"}, {"id": "f1", "type": "textarea", "label": "What I will do with my feet, my breath and my eyes while I wait:"}, {"id": "f2", "type": "textarea", "label": "The sentence I will say to the person behind me if I need to step aside:"}, {"id": "f3", "type": "textarea", "label": "The time I will arrive, so the clock is not part of the surge:"}, {"id": "f4", "type": "textarea", "label": "What I will do in the first five minutes after getting through:"}, {"id": "f5", "type": "textarea", "label": "Afterward: what happened in the line, and what I would tell myself next time:"}]'::jsonb, array['panic attacks', 'planning', 'exposure']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('shortness-of-breath-means-i-will-suffocate-fact-check-sheet', 'Shortness of Breath Means I Will Suffocate Fact Check Sheet', 'cbt'::resource_kind, 'A fact check for the panic thought that a tight chest and short breath mean the client will stop breathing.', 'Use it to put the suffocation prediction against what the client knows about breath, panic and every past surge.', array['Adults', 'Teens']::text[], '20 minutes', 'The breath shortens, the chest tightens, and the mind announces that the air is running out. The sheet has the client write the sensation and the prediction, the belief in it at the peak and now, and then the facts: how many surges they have had, how many ended in suffocation, what happens to breathing when a person overbreathes, and what the body does on its own when they hold their breath. Make sure the client''s health history is known before testing breath holds. Watch for a client who agrees in session and still rushes for air at the peak; the sentence needs rehearsal.', '[{"id": "f0", "type": "textarea", "label": "The sensation, and the prediction my mind makes about it:"}, {"id": "f1", "type": "textarea", "label": "My belief in the prediction at the peak, and my belief now (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "How many surges I have had, and how many ended the way the prediction said:"}, {"id": "f3", "type": "textarea", "label": "What I know about what overbreathing does to the chest and the head:"}, {"id": "f4", "type": "textarea", "label": "A balanced sentence short enough to say at the peak:"}, {"id": "f5", "type": "textarea", "label": "The next surge: what happened to my breath, and whether the sentence came to mind:"}]'::jsonb, array['panic attacks', 'thinking traps', 'predictions']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('panic-as-a-car-alarm-set-off-by-the-wind-page', 'Panic as a Car Alarm Set Off by the Wind Page', 'act'::resource_kind, 'An ACT page that pictures a surge as a car alarm the wind set off: loud, pointless and not a sign of a break-in.', 'Use it to help a client let the alarm run its course without treating every surge as proof of danger.', array['Adults', 'Teens']::text[], '15 minutes', 'A car alarm in the night is loud and insistent, and almost always nothing: a gust, a truck going by. The page has the client describe their alarm (what sets it off, how loud, how long it runs), what they do when it sounds (run outside to check, argue with it, hide), and what the car alarm image suggests instead: let it run, keep doing what they were doing, notice when it stops on its own. Watch for a client who hears this as being told the surge is fake; the alarm is real and loud, it is only the break-in that is not happening.', '[{"id": "f0", "type": "textarea", "label": "My alarm: what sets it off, how loud it gets, and how long it usually runs:"}, {"id": "f1", "type": "textarea", "label": "What I do when it sounds: check, argue, hide, call someone:"}, {"id": "f2", "type": "textarea", "label": "What letting it run would look like for me, in the place it most often sounds:"}, {"id": "f3", "type": "textarea", "label": "The sentence I will say to myself when it goes off:"}, {"id": "f4", "type": "textarea", "label": "One alarm this week I let run, and when it stopped:"}, {"id": "f5", "type": "textarea", "label": "What I kept doing while it ran, that I would have stopped before:"}]'::jsonb, array['panic attacks', 'acceptance', 'metaphor']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('tipp-paced-breathing-in-the-parked-car-card', 'TIPP Paced Breathing in the Parked Car Card', 'dbt'::resource_kind, 'A paced breathing card for the parked car, the place many clients sit before they can go in anywhere.', 'Use it to turn the minutes in the parked car from waiting for the surge to pass into a skill the client runs on purpose.', array['Adults', 'Teens']::text[], '5 minutes, used in the car', 'The client finds their paced breathing count in session (a longer exhale than inhale), then writes the routine for the parked car outside the store or the office: seat back, hands on the wheel or the lap, eyes on one thing, the count for two minutes. They rate the surge before and after and set a rule for when they will open the door (after the two minutes, not when the surge is gone). Watch for a client who extends the breathing until the surge ends; the car is a launch point, not a waiting room.', '[{"id": "f0", "type": "textarea", "label": "My paced breathing count, found in session (in for how long, out for how long):"}, {"id": "f1", "type": "textarea", "label": "The routine in the car, step by step, from engine off to the end of two minutes:"}, {"id": "f2", "type": "textarea", "label": "The surge before and after the two minutes (0 to 10):"}, {"id": "f3", "type": "textarea", "label": "My door rule: when I open it, whatever the surge is doing:"}, {"id": "f4", "type": "textarea", "label": "The parked car this week: where, what I did, and when the door opened:"}, {"id": "f5", "type": "textarea", "label": "What the first two minutes inside were like:"}]'::jsonb, array['panic attacks', 'TIPP', 'distress tolerance']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('what-not-to-say-during-a-surge-list-for-partners', 'What Not to Say During a Surge List for Partners', 'couples'::resource_kind, 'A list made together of what the partner should not say during a surge, and what to say instead.', 'Use it to turn a partner''s well-meant lines that make a surge worse into a short script that helps.', array['Couples']::text[], '25 minutes', 'Partners mean well and often say the worst things: calm down, there is nothing wrong with you, not again. The sheet has the partner who has surges list the lines that make it worse and why, and the lines that would help (I am here, take your time, do you want me to talk or be quiet). The other partner writes what they tend to say and how it feels to watch a surge, which is often frightening and worth saying aloud. Watch for the supporting partner feeling blamed; the sheet asks the partner with surges to write one thing the other has done that helped.', '[{"id": "f0", "type": "textarea", "label": "Partner with surges: the lines that make it worse, and why each one does:"}, {"id": "f1", "type": "textarea", "label": "Partner with surges: the lines that would help, and the kind of help I usually want:"}, {"id": "f2", "type": "textarea", "label": "Other partner: what I tend to say, and what watching a surge is like for me:"}, {"id": "f3", "type": "textarea", "label": "Together: our three-line script for the first minute of a surge:"}, {"id": "f4", "type": "textarea", "label": "The signal for talk to me, and the signal for stay quiet and stay close:"}, {"id": "f5", "type": "textarea", "label": "Partner with surges: one thing you have done during a surge that helped:"}]'::jsonb, array['panic attacks', 'couples', 'support']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('screen-time-handover-without-a-fight-steps-sheet', 'Screen Time Handover Without a Fight Steps Sheet', 'worksheet'::resource_kind, 'A steps sheet for the daily moment screens go off, with warnings, a landing activity and a plan for the protest.', 'Use it to help a parent script the screen handover so it runs the same way every day and the fight shrinks.', array['Adults']::text[], '25 minutes', 'The end of screen time is a daily fight in many homes because it arrives without warning and lands the child in nothing. The sheet has the parent write the current handover as it actually goes, then build the new one: a ten-minute and a two-minute warning, the child''s own job of pausing at a stopping point, the landing activity that is ready when the screen goes dark, and the parent''s two sentences for the protest, said once. A week of tallies shows whether the fight is shrinking. Watch for a parent who negotiates after the warnings; the sheet has them write what they will not say.', '[{"id": "f0", "type": "textarea", "label": "The handover as it goes now, from the first warning to the end of the fight:"}, {"id": "f1", "type": "textarea", "label": "The warnings I will give, and the words I will use for each:"}, {"id": "f2", "type": "textarea", "label": "The landing activity that will be ready when the screen goes off:"}, {"id": "f3", "type": "textarea", "label": "My two sentences for the protest, said once, and what I will not say:"}, {"id": "f4", "type": "textarea", "label": "Each day this week: how long the protest lasted, 0 to 10 for heat:"}, {"id": "f5", "type": "textarea", "label": "What I will change for next week:"}]'::jsonb, array['parenting', 'routines', 'boundaries']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('my-childs-tantrum-means-i-am-doing-it-wrong-sheet', 'My Child''s Tantrum Means I Am Doing It Wrong Sheet', 'cbt'::resource_kind, 'A thought check for the parent who reads every public meltdown as a verdict on their parenting.', 'Use it to separate the tantrum, which small children have, from the conclusion the parent draws about themselves.', array['Adults']::text[], '20 minutes', 'The meltdown in the store ends, and the parent carries the verdict home: a better parent would have prevented that. The sheet takes the moment apart: what the child did, what the parent did, and the thought about what it meant. Then the evidence: what the parent knows about children of that age and tired afternoons, what they would say to a friend whose child did the same, and what they actually handled well in the moment. Watch for the parent who accepts that tantrums are normal in general but not for their child.', '[{"id": "f0", "type": "textarea", "label": "The meltdown: where, what my child did, and what I did:"}, {"id": "f1", "type": "textarea", "label": "The thought about what it meant about me, and how much I believed it:"}, {"id": "f2", "type": "textarea", "label": "What I know about children this age, this time of day, this kind of situation:"}, {"id": "f3", "type": "textarea", "label": "What I would say to a friend whose child did exactly this:"}, {"id": "f4", "type": "textarea", "label": "What I actually handled well in the moment, even if small:"}, {"id": "f5", "type": "textarea", "label": "A balanced thought, and one thing to try next time that is about the situation:"}]'::jsonb, array['parenting', 'thinking traps', 'self-criticism']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('values-at-the-homework-table-page', 'Values at the Homework Table Page', 'act'::resource_kind, 'A values page for the nightly homework battle, choosing the parent the client wants to be at that table.', 'Use it to help a parent act from values at the homework table instead of from the urge to get it done.', array['Adults']::text[], '20 minutes', 'Homework turns many kind parents into supervisors who hover, correct and raise their voices, and the evening ends with everyone miserable. The page has the parent describe the table as it is, name what pulls them (the clock, the fear of the teacher''s note, the wish for it to be over), and then the values: what kind of parent they want to be in that chair, and what their child would say about them at the table in ten years. Watch for a parent who turns the values into a new standard to fail at; the page is a direction, not a grade.', '[{"id": "f0", "type": "textarea", "label": "The homework table as it is now: what I do, what my child does, how it ends:"}, {"id": "f1", "type": "textarea", "label": "What pulls me into hovering and correcting:"}, {"id": "f2", "type": "textarea", "label": "The parent I want to be in that chair, in a few words:"}, {"id": "f3", "type": "textarea", "label": "What I hope my child will say about homework with me in ten years:"}, {"id": "f4", "type": "textarea", "label": "Two concrete moves for tomorrow night that come from those values:"}, {"id": "f5", "type": "textarea", "label": "After the week: which moves I made, and what the table was like:"}]'::jsonb, array['parenting', 'values', 'committed action']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('give-skill-when-my-teen-shares-something-small-card', 'GIVE Skill When My Teen Shares Something Small Card', 'dbt'::resource_kind, 'A GIVE card for the moment a teenager offers a small piece of their day, which is often the only door that opens.', 'Use it to help a parent be gentle, interested, validating and easy when a teen says something small, so they say more.', array['Adults']::text[], '15 minutes', 'Teenagers rarely announce the important thing; they drop something small while getting a snack and watch what the parent does with it. GIVE is Gentle, Interested, Validate, Easy manner. The card has the parent recall a recent small offering and what they did with it (a lecture, a question too many, a correction, a glance at the phone), then script each letter for next time: a soft tone, one curious question, a sentence that shows the parent gets why it matters, and a light touch that leaves the door open. Watch for a parent whose interest tips into interrogation; one question, then wait.', '[{"id": "f0", "type": "textarea", "label": "A small thing my teen shared recently, and what I did with it:"}, {"id": "f1", "type": "textarea", "label": "Gentle: the tone and face I will have the next time, and what I will not do:"}, {"id": "f2", "type": "textarea", "label": "Interested: the one curious question I will ask, and then the waiting:"}, {"id": "f3", "type": "textarea", "label": "Validate: the sentence that shows I get why this matters to them:"}, {"id": "f4", "type": "textarea", "label": "Easy manner: how I will keep it light so the door stays open:"}, {"id": "f5", "type": "textarea", "label": "This week: a small thing shared, what I did with it, and whether more followed:"}]'::jsonb, array['parenting', 'GIVE', 'interpersonal effectiveness']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('family-high-low-dinner-spinner-craft', 'Family High Low Dinner Spinner Craft', 'kids'::resource_kind, 'A paper spinner for the dinner table that lands on a question (high, low, surprise, kind thing) each person answers.', 'Use it to give a family a daily two-minute check-in the child runs, with the parent answering honestly too.', array['Children']::text[], '25 minutes to make, used at dinner', 'The child makes a paper plate spinner with a paper fastener arrow and four to six sections: my high today, my low today, something that surprised me, something kind I saw, a question for everyone, spinner''s choice. At dinner the child spins for each person in turn and that person answers in a sentence; the parent answers honestly about their own low, which shows the child that lows are allowed at the table. No fixing anyone''s low during the game; the parent can return to it later. Watch for a parent who turns a child''s low into a lesson; the rule is to say thanks for telling us and spin again.', '[{"id": "f0", "type": "textarea", "label": "Draw your spinner here with its sections:"}, {"id": "f1", "type": "textarea", "label": "My high and my low from today:"}, {"id": "f2", "type": "textarea", "label": "What did a grown-up say when the spinner landed on their low?"}, {"id": "f3", "type": "textarea", "label": "Grown-up: a low I shared, and how my child responded to it:"}, {"id": "f4", "type": "textarea", "label": "What question would you add to the spinner?"}]'::jsonb, array['parenting', 'children', 'craft']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('night-feed-phone-scroll-swap-list-sheet', 'Night Feed Phone Scroll Swap List Sheet', 'worksheet'::resource_kind, 'A swap list for the 3 a.m. feed, replacing the doom scroll with things that rest the mind as well as the arms.', 'Use it to give a new parent a short menu for the night feed that does not leave them more wired than before.', array['Adults']::text[], '15 minutes', 'The night feed is dark, long and boring, and the phone is right there, so many new parents spend it reading things that leave them more anxious at 3:30 than they were at 3. The sheet has the parent write what they usually look at and how they feel when the feed ends, then build a swap list: an audiobook at low volume, a playlist, a podcast with no news, looking at the baby, a dim room and nothing at all. Watch for a parent who uses the scroll to stay awake and fears falling asleep holding the baby; address the safety piece first.', '[{"id": "f0", "type": "textarea", "label": "What I usually look at during the night feed, and how I feel when it ends:"}, {"id": "f1", "type": "textarea", "label": "My swap list: things that rest my mind as well as my arms:"}, {"id": "f2", "type": "textarea", "label": "The two I will try this week, and where they will be ready before bed:"}, {"id": "f3", "type": "textarea", "label": "Each night: what I used, and how the end of the feed felt (0 to 10 for wired):"}, {"id": "f4", "type": "textarea", "label": "If I use the phone to stay awake: what else will keep me safely awake:"}, {"id": "f5", "type": "textarea", "label": "What I will keep from this list once the night feeds end:"}]'::jsonb, array['perinatal and postpartum', 'sleep', 'routines']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('the-baby-cries-because-i-am-doing-it-wrong-thought-record', 'The Baby Cries Because I Am Doing It Wrong Thought Record', 'cbt'::resource_kind, 'A thought record for the new parent who hears every cry as evidence against themselves.', 'Use it to separate the baby''s crying, which babies do, from the parent''s conclusion about their competence.', array['Adults']::text[], '20 minutes', 'A crying baby that will not settle is wired to feel like a failure, and tired parents turn the feeling into a fact. The record has the parent write a specific cry (when, how long, what they tried), the thought about what it meant, and the belief in it. Then the evidence: what they know about how much babies cry at this age, what settled the baby other times, what the pediatrician or a nurse has said, and what a friend would say watching them. Watch for a parent whose belief does not move; persistent low mood or fear needs its own attention.', '[{"id": "f0", "type": "textarea", "label": "The cry: when, how long, and what I tried:"}, {"id": "f1", "type": "textarea", "label": "The thought about what it meant about me, and how much I believed it (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "What I know about how much babies cry at this age, and what has settled this baby before:"}, {"id": "f3", "type": "textarea", "label": "What a nurse, the pediatrician or a friend watching me would say:"}, {"id": "f4", "type": "textarea", "label": "A balanced thought I can say to myself at 2 a.m.:"}, {"id": "f5", "type": "textarea", "label": "The next long cry: what I will do, and who I will hand the baby to if I need a break:"}]'::jsonb, array['perinatal and postpartum', 'thought record', 'self-criticism']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('values-when-the-baby-will-not-nap-page', 'Values When the Baby Will Not Nap Page', 'act'::resource_kind, 'A values page for the hour the nap fails and the plan for the hour fails with it.', 'Use it to help a new parent choose how to be in the no-nap hour instead of fighting the hour itself.', array['Adults']::text[], '15 minutes', 'When the baby will not go down, the parent is left with a wide-awake infant and a head full of the plan. The page has the parent describe the no-nap hour as it goes now, what they fight (the baby, the clock, themselves), and then the values: what matters to them about being with this baby, even on the days the baby will not cooperate. From the values they pick one way to spend the next failed nap and let the plan go for that hour. Watch for a parent who hears this as giving up on rest; rest gets its own plan elsewhere.', '[{"id": "f0", "type": "textarea", "label": "The no-nap hour as it goes now, including what I fight:"}, {"id": "f1", "type": "textarea", "label": "The plan I had for the nap, and what losing it feels like:"}, {"id": "f2", "type": "textarea", "label": "What matters to me about being with this baby, even on uncooperative days:"}, {"id": "f3", "type": "textarea", "label": "One way I will spend the next failed nap that comes from that:"}, {"id": "f4", "type": "textarea", "label": "Where rest will come from instead this week, and who will help:"}, {"id": "f5", "type": "textarea", "label": "After the next failed nap: what I did, and how the hour felt:"}]'::jsonb, array['perinatal and postpartum', 'values', 'acceptance']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('self-validation-after-a-hard-day-with-the-baby-card', 'Self-Validation After a Hard Day With the Baby Card', 'dbt'::resource_kind, 'A self-validation card for the end of a day with a baby that went badly, written before bed instead of the replay.', 'Use it to give a new parent a two-minute practice that acknowledges the day without grading it.', array['Adults']::text[], 'Five minutes at bedtime', 'New parents end hard days replaying what went wrong, and the replay follows them to sleep. Self-validation is the DBT skill of saying to oneself what a kind, accurate observer would say: of course this was hard, here is what made it hard, here is what I did anyway. The card has the parent write the facts of the day without judgment, the feelings that make sense given those facts, one thing they did that counted, and a sentence they will say to themselves before turning off the light. Watch for a parent who validates and then adds but; the card ends before the but.', '[{"id": "f0", "type": "textarea", "label": "The facts of today, described without any verdict:"}, {"id": "f1", "type": "textarea", "label": "The feelings I had, and why they make sense given those facts:"}, {"id": "f2", "type": "textarea", "label": "One thing I did today that counted, however small:"}, {"id": "f3", "type": "textarea", "label": "The sentence I will say to myself before I turn off the light:"}, {"id": "f4", "type": "textarea", "label": "What I am tempted to add after but, and why I am leaving it off tonight:"}, {"id": "f5", "type": "textarea", "label": "Tomorrow: one thing I need, and who I will ask for it:"}]'::jsonb, array['perinatal and postpartum', 'self-validation', 'core DBT']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('baby-appointment-and-supply-tracking-split-for-new-parents', 'Baby Appointment and Supply Tracking Split for New Parents', 'couples'::resource_kind, 'A split of the invisible baby logistics: appointments, diaper counts, formula or milk supply, growth notes, forms.', 'Use it to make the tracking work of a new baby visible and divide it so one parent is not holding it all.', array['Couples']::text[], '30 minutes', 'One parent usually becomes the one who knows when the next appointment is, how many diapers are left and which size comes next, and the other does not know how much knowing that takes. The sheet lists the tracking tasks one by one, each parent marks which ones they currently hold, and the one holding most describes what it is like. Then they reassign: whole tasks, not halves, so each has things they own completely, and agree on where the shared information lives. Watch for the parent giving up tasks and then checking them anyway; the sheet asks them to name one task they will truly let go of.', '[{"id": "f0", "type": "textarea", "label": "All the tracking tasks for the baby, listed one by one:"}, {"id": "f1", "type": "textarea", "label": "Who currently holds each one, marked honestly:"}, {"id": "f2", "type": "textarea", "label": "Parent holding most: what carrying all of this is like for me:"}, {"id": "f3", "type": "textarea", "label": "The reassignment: whole tasks each of us now owns completely:"}, {"id": "f4", "type": "textarea", "label": "Where the shared information will live so neither of us has to ask the other:"}, {"id": "f5", "type": "textarea", "label": "Parent letting go: the one task I will truly stop checking, and how I will know I have:"}]'::jsonb, array['perinatal and postpartum', 'couples', 'fairness']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('asking-for-help-without-over-explaining-log-sheet', 'Asking for Help Without Over-Explaining Log Sheet', 'worksheet'::resource_kind, 'A log of requests for help, counting the words of justification the client adds before and after the ask.', 'Use it to make visible how much a client apologizes for needing anything, and to practice the plain ask.', array['Adults', 'Teens']::text[], 'One week', 'Clients who feel they do not deserve help ask for it wrapped in explanation: sorry, I know you are busy, it is probably nothing, I would not ask but. The log has them record each request for a week, with a count of the justifying sentences before and after the actual ask, the reply they got, and whether the explanation changed the reply. Then they practice one plain ask a day: the request and a thank you, nothing else, and record how that lands. Watch for the client who stops asking rather than over-explaining; the plain ask is the target, not silence.', '[{"id": "f0", "type": "textarea", "label": "Each request this week: what I asked, how many justifying sentences before and after, and the reply:"}, {"id": "f1", "type": "textarea", "label": "What I notice about the justifications: the phrases I use most:"}, {"id": "f2", "type": "textarea", "label": "Did the explanation ever change the reply? What did?"}, {"id": "f3", "type": "textarea", "label": "One plain ask a day: the request and a thank you, and how it landed:"}, {"id": "f4", "type": "textarea", "label": "What I felt in the pause after a plain ask, and what I wanted to add:"}, {"id": "f5", "type": "textarea", "label": "The ask I have been avoiding, written plainly, ready to use:"}]'::jsonb, array['self-esteem', 'assertiveness', 'self-monitoring']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('if-they-knew-the-real-me-thought-record', 'If They Knew the Real Me Thought Record', 'cbt'::resource_kind, 'A thought record for the belief that the client''s acceptance by others depends on hiding who they really are.', 'Use it to look at the hidden self the client fears is unacceptable and test what has happened when parts have been seen.', array['Adults', 'Teens']::text[], '25 minutes', 'The thought is that the people who like the client like a performance, and the real one would be rejected. The record has the client write the situation that brought it up, the thought and belief in it, the feeling, and then what exactly the real me is that they are hiding (often it is ordinary: moods, opinions, needs). Then the evidence: times a part of the real self has shown and what happened, people who have seen more than most and stayed, and what the client knows about the hidden selves of others. Watch for a disclosure chosen for maximum risk; start small.', '[{"id": "f0", "type": "textarea", "label": "The situation that brought up the thought, and the thought itself:"}, {"id": "f1", "type": "textarea", "label": "My belief in it (0 to 100), and what I felt:"}, {"id": "f2", "type": "textarea", "label": "The real me I am afraid would be rejected, written out specifically:"}, {"id": "f3", "type": "textarea", "label": "Times a part of that has shown, and what actually happened:"}, {"id": "f4", "type": "textarea", "label": "People who have seen more than most, and what they did:"}, {"id": "f5", "type": "textarea", "label": "A balanced thought, and one small piece of the real me I will let show this week:"}]'::jsonb, array['self-esteem', 'thought record', 'core beliefs']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('worth-as-a-given-not-a-grade-page', 'Worth as a Given Not a Grade Page', 'act'::resource_kind, 'An ACT page that pulls worth out of the grading system the client runs on themselves and treats it as already settled.', 'Use it to help a client notice the grading mind at work and act from values without waiting for a passing score.', array['Adults', 'Teens']::text[], '20 minutes', 'Many clients run a constant grading system on themselves and treat worth as the score. The page has the client describe their grading mind: what it grades (looks, output, how they came across), how often, and what grade they got today. Then it offers the alternative: worth as a given, like the ground under the feet, not something earned by the day''s score. The client names what they would do today if worth were already settled, and does one of those things before tomorrow. Watch for a client who tries to argue their way to a better grade; the move is to step off the scale, not to climb it.', '[{"id": "f0", "type": "textarea", "label": "What my grading mind grades, how often, and what grade I got today:"}, {"id": "f1", "type": "textarea", "label": "What the grading has cost me this week in time, choices and rest:"}, {"id": "f2", "type": "textarea", "label": "If worth were a given and not a grade, what I would do today that I am not doing:"}, {"id": "f3", "type": "textarea", "label": "The one thing from that list I will do before tomorrow:"}, {"id": "f4", "type": "textarea", "label": "What the grading mind said while I did it:"}, {"id": "f5", "type": "textarea", "label": "A sentence for the next time I catch the mind handing out a grade:"}]'::jsonb, array['self-esteem', 'self-as-context', 'values']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('cheerleading-statements-before-asking-for-a-raise-card', 'Cheerleading Statements Before Asking for a Raise Card', 'dbt'::resource_kind, 'A cheerleading statements card for the walk into the meeting where the client asks for more money.', 'Use it to give a client the sentences they will say to themselves before an ask they believe they do not deserve.', array['Adults']::text[], '20 minutes', 'Cheerleading statements are the self-talk that gets a person through an interpersonal situation, and asking for a raise is where many clients fall silent. The card has the client write what their mind says on the walk to the meeting (who do you think you are, they will laugh), then the cheerleading statements that answer each: the facts of what they have done, the fact that asking is normal, the reminder that a no is survivable. Watch for a statement the client does not believe; it must be true, not just encouraging.', '[{"id": "f0", "type": "textarea", "label": "What my mind says on the walk to the meeting:"}, {"id": "f1", "type": "textarea", "label": "The facts of what I have done that make the ask reasonable:"}, {"id": "f2", "type": "textarea", "label": "My cheerleading statements, one answering each line my mind uses:"}, {"id": "f3", "type": "textarea", "label": "The one statement I will say to myself at the door:"}, {"id": "f4", "type": "textarea", "label": "What I will say to myself if the answer is no:"}, {"id": "f5", "type": "textarea", "label": "After the meeting: what I asked for, what happened, and which statement helped:"}]'::jsonb, array['self-esteem', 'cheerleading statements', 'interpersonal effectiveness']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('pass-the-mic-something-i-did-well-this-week-game', 'Pass the Mic Something I Did Well This Week Game', 'game'::resource_kind, 'A circle game with a toy microphone where each person must say one thing they did well this week, no deflecting allowed.', 'Use it to get a group practicing plain self-credit out loud, with a rule against softening it, and a debrief.', array['Groups', 'Teens', 'Adults']::text[], '25 minutes', 'A toy microphone goes around the circle. Whoever holds it says one thing they did well this week, in one sentence, with no softener (no but, no it was nothing, no anyone could have). If a softener slips out, the group says mic check and the speaker tries again. Listeners respond only with a nod or a thank you, no praise. Debrief: what it was like to say it plainly, which softener kept trying to get in, and whether it got easier by round three. Watch for a member who cannot find one thing; the group may offer one, and the member must say it in their own words.', '[{"id": "f0", "type": "textarea", "label": "Round one: the thing I did well, as I said it into the mic:"}, {"id": "f1", "type": "textarea", "label": "The softener that kept trying to get into my sentence:"}, {"id": "f2", "type": "textarea", "label": "Rounds two and three: what I said, and whether it got easier:"}, {"id": "f3", "type": "textarea", "label": "What it was like to hear others say theirs plainly:"}, {"id": "f4", "type": "textarea", "label": "Debrief: one place this week I will say what I did well without a softener:"}]'::jsonb, array['self-esteem', 'game', 'group']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('joining-a-conversation-already-in-progress-steps-sheet', 'Joining a Conversation Already in Progress Steps Sheet', 'worksheet'::resource_kind, 'A steps sheet for walking up to a group that is already talking, from the approach to the first sentence.', 'Use it to break the hardest social moment into steps a client can rehearse and then try at a real gathering.', array['Adults', 'Teens']::text[], '25 minutes', 'Starting a conversation is hard; joining one already going is harder, and many clients stand at the edge of the room all night rather than attempt it. The sheet lays out the steps: pick a group of three or more (two is a private conversation), stand at the edge and listen for a minute, catch someone''s eye and smile, step in on a laugh or a pause, and say one of three prepared lines (a question about what they were saying, an agreement, an introduction). Watch for the client who rates the attempt by how witty they were; the attempt counts.', '[{"id": "f0", "type": "textarea", "label": "The gathering where I will try this, and when:"}, {"id": "f1", "type": "textarea", "label": "The kind of group I will pick, and how I will know they are open:"}, {"id": "f2", "type": "textarea", "label": "My three joining lines, written out:"}, {"id": "f3", "type": "textarea", "label": "My exit line for when I want to move on:"}, {"id": "f4", "type": "textarea", "label": "The attempt: which step was hardest, what I said, and what happened:"}, {"id": "f5", "type": "textarea", "label": "What I will do the same and differently at the next gathering:"}]'::jsonb, array['social anxiety', 'exposure', 'planning']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('everyone-saw-my-hands-shake-thought-record', 'Everyone Saw My Hands Shake Thought Record', 'cbt'::resource_kind, 'A thought record for the moment the client''s hands tremble in public and the mind decides everyone noticed and judged.', 'Use it to test the belief that a visible sign of nerves was seen by everyone and meant something bad to them.', array['Adults', 'Teens']::text[], '20 minutes', 'The hands shake while signing, pouring or holding a cup, and the client is certain the whole room saw and concluded something. The record has the client write the moment, the thought (everyone saw, they think I am a mess), the belief and the feeling, and then the evidence: who was actually looking, what the client has concluded about other people''s shaking hands, and what someone would have to be doing to notice. Watch for the client who hides their hands as the solution; hiding is the behavior to test.', '[{"id": "f0", "type": "textarea", "label": "The moment: what my hands were doing, and who was there:"}, {"id": "f1", "type": "textarea", "label": "The thought about who saw and what they concluded, and my belief in it (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "Who was actually looking at my hands, as far as I can tell:"}, {"id": "f3", "type": "textarea", "label": "What I have concluded about other people when their hands shook:"}, {"id": "f4", "type": "textarea", "label": "A balanced thought about what was seen and what it meant:"}, {"id": "f5", "type": "textarea", "label": "The experiment: where I let my hands shake, and what the trusted person said they saw:"}]'::jsonb, array['social anxiety', 'thought record', 'thinking traps']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('walking-in-as-the-observer-not-the-observed-page', 'Walking In as the Observer Not the Observed Page', 'act'::resource_kind, 'A perspective page that moves the client from being watched to watching when they walk into a room.', 'Use it to help a client shift attention outward in social situations and notice what the shift does to the fear.', array['Adults', 'Teens']::text[], '15 minutes', 'A client with social fear walks into a room already filmed from the outside: what do I look like, how am I standing. The page has the client describe that camera, then practice turning it around: on entering, notice three things about the room and two about a person in it, as if they were there to report on the scene. The client picks an upcoming entrance and afterward records what they saw and what happened to the attention on themselves. Watch for a client who turns observing into checking for judgment; the task is to notice the room, not to scan it for threat.', '[{"id": "f0", "type": "textarea", "label": "The camera on me when I walk in: what it films, and what it says:"}, {"id": "f1", "type": "textarea", "label": "The upcoming entrance where I will turn the camera around:"}, {"id": "f2", "type": "textarea", "label": "What I will look for: three things about the room, two about a person:"}, {"id": "f3", "type": "textarea", "label": "Afterward: what I actually saw:"}, {"id": "f4", "type": "textarea", "label": "What happened to the attention on myself while I was looking outward:"}, {"id": "f5", "type": "textarea", "label": "One thing I learned about someone else that I would have missed:"}]'::jsonb, array['social anxiety', 'present moment', 'self-as-context']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('opposite-action-to-hiding-in-the-bathroom-at-the-party-card', 'Opposite Action to Hiding in the Bathroom at the Party Card', 'dbt'::resource_kind, 'An opposite action card for the party escape to the bathroom, with the steps back into the room written out.', 'Use it to give a client a plan for the moment they want to hide, acting opposite to the urge in small steps.', array['Adults', 'Teens']::text[], '15 minutes', 'The bathroom at a party is a refuge many clients know too well: five minutes becomes twenty, and the night is spent there. Opposite action asks whether the fear fits the facts and whether hiding works, and when it does not, to approach instead, all the way: back into the room, shoulders down, toward one person, with one sentence ready. Watch for a client who approaches the room and hides in the corner of it; the card names the person, not the room.', '[{"id": "f0", "type": "textarea", "label": "My hiding: where, how long, and what I tell myself in there:"}, {"id": "f1", "type": "textarea", "label": "Does the fear fit the facts, and is the hiding working for me?"}, {"id": "f2", "type": "textarea", "label": "My time limit in the bathroom, and what I will do at the end of it:"}, {"id": "f3", "type": "textarea", "label": "The person I will walk toward, and the sentence I will say:"}, {"id": "f4", "type": "textarea", "label": "What my body will do on the way: shoulders, breath, eyes:"}, {"id": "f5", "type": "textarea", "label": "After the party: how long I hid, who I walked toward, and what happened:"}]'::jsonb, array['social anxiety', 'opposite action', 'core DBT']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('compliment-a-stranger-mission-debrief-game', 'Compliment a Stranger Mission Debrief Game', 'game'::resource_kind, 'A group mission game: each member gives one real compliment to a stranger before the next session and reports back.', 'Use it to get a group approaching strangers with something kind to say, and to compare predictions with results.', array['Groups', 'Teens', 'Adults']::text[], '20 minutes to set up, 25 minutes to debrief', 'In the first session each member chooses a mission level: a compliment to a cashier about their efficiency, to a stranger about their dog, to someone in line about their jacket. They write their prediction (how the stranger will react, how awkward it will be) and seal it. At the debrief each member reads their prediction, then tells what happened; a point for each mission done and a bonus for the biggest gap. Debrief: what did strangers actually do, and what does that suggest about the predictions. Watch for a member who completed the mission by text; it has to be face to face.', '[{"id": "f0", "type": "textarea", "label": "My mission and its level:"}, {"id": "f1", "type": "textarea", "label": "My sealed prediction: how they will react, and how awkward it will be (0 to 10):"}, {"id": "f2", "type": "textarea", "label": "What actually happened, in their words and mine:"}, {"id": "f3", "type": "textarea", "label": "The gap between my prediction and the result:"}, {"id": "f4", "type": "textarea", "label": "Debrief: what strangers in our group''s missions actually did, and my next mission:"}]'::jsonb, array['social anxiety', 'game', 'behavioral experiment']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('their-birthday-this-year-plan-sheet', 'Their Birthday This Year Plan Sheet', 'worksheet'::resource_kind, 'A plan for the first birthday of someone who has died, deciding what to do with the day before it arrives.', 'Use it to help a grieving client choose how the birthday will go instead of being ambushed by it.', array['Adults', 'Teens']::text[], '25 minutes, a week or two before the date', 'The birthday of someone who has died arrives on the calendar whether the client is ready or not, and many spend it either pretending it is an ordinary day or lost in it. The sheet has the client decide: who they want to be with, whether and how they will mark it (the cake, the restaurant, the grave, a message to others who loved them), what they will do if the day turns out worse than planned, and what they will do if it turns out easier, which brings its own guilt. Watch for a client who plans the day for other mourners and leaves themselves out; the sheet asks what they want for themselves.', '[{"id": "f0", "type": "textarea", "label": "The date, and what we used to do on it:"}, {"id": "f1", "type": "textarea", "label": "Who I want to be with that day, and who I want to tell in advance:"}, {"id": "f2", "type": "textarea", "label": "How I will mark it, if I will, in my own way:"}, {"id": "f3", "type": "textarea", "label": "What I will do if the day is worse than I planned for:"}, {"id": "f4", "type": "textarea", "label": "What I will tell myself if the day turns out easier than I feared:"}, {"id": "f5", "type": "textarea", "label": "Afterward: what the day was like, and what I would keep for next year:"}]'::jsonb, array['grief and loss', 'planning', 'support']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('keeping-their-room-the-same-means-i-am-stuck-check-sheet', 'Keeping Their Room the Same Means I Am Stuck Check Sheet', 'cbt'::resource_kind, 'A thought check for the client who reads their own pace with a loved one''s belongings as a sign of being stuck.', 'Use it to separate the client''s choice about a room or belongings from the verdict they attach to that choice.', array['Adults', 'Teens']::text[], '20 minutes', 'The room is as it was, or the closet is still full, and someone has suggested that this means the client is not moving on. The sheet has the client write the thought and who first said it (often themselves), the belief in it, and then the evidence: what they have done in other parts of life since the death, what the room gives them, what other grieving people they know have done with belongings and over what time, and what a friend would say. Watch for the client who rushes to clear the room to prove the thought wrong.', '[{"id": "f0", "type": "textarea", "label": "The thought about what keeping things the same means, and who first said it:"}, {"id": "f1", "type": "textarea", "label": "My belief in it (0 to 100), and what I feel when I think it:"}, {"id": "f2", "type": "textarea", "label": "What I have done in other parts of my life since the death:"}, {"id": "f3", "type": "textarea", "label": "What the room or the belongings give me right now:"}, {"id": "f4", "type": "textarea", "label": "What other grieving people I know have done, and over what time:"}, {"id": "f5", "type": "textarea", "label": "A balanced thought, and a decision about the room that is mine and not a test:"}]'::jsonb, array['grief and loss', 'thinking traps', 'self-criticism']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('love-and-grief-two-sides-of-one-coin-page', 'Love and Grief Two Sides of One Coin Page', 'act'::resource_kind, 'An acceptance page that puts grief and love on the same coin, so the client stops trying to spend one without the other.', 'Use it to help a client make room for grief as the other face of the love they do not want to give up.', array['Adults', 'Teens']::text[], '15 minutes', 'The client writes what they loved about the person on one side and what they grieve on the other, and sees how each line matches: the laugh they miss is the laugh they loved. Then they describe what trying to put the coin down has looked like (staying busy, avoiding photos, not saying the name) and what carrying it would look like this week: one moment of love and grief together, on purpose. Watch for a client who hears this as being told to hurt more; the page is about not splitting what cannot be split.', '[{"id": "f0", "type": "textarea", "label": "One side of the coin: what I loved about them, line by line:"}, {"id": "f1", "type": "textarea", "label": "The other side: what I grieve, line by line, next to the matching love:"}, {"id": "f2", "type": "textarea", "label": "What trying to put the coin down has looked like for me:"}, {"id": "f3", "type": "textarea", "label": "What carrying it would look like this week: one moment of both, on purpose:"}, {"id": "f4", "type": "textarea", "label": "After that moment: what the grief did, and what the love did:"}, {"id": "f5", "type": "textarea", "label": "Where I will keep the coin: the place or habit where I let both be present:"}]'::jsonb, array['grief and loss', 'acceptance', 'metaphor']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('self-soothe-with-their-favorite-song-card', 'Self-Soothe With Their Favorite Song Card', 'dbt'::resource_kind, 'A self-soothe card that uses the song a loved one played most, approached on purpose with the body prepared.', 'Use it to help a client turn a song they have been avoiding into a chosen moment of comfort and connection.', array['Adults', 'Teens']::text[], '15 minutes to prepare, used when chosen', 'The song comes on in a store and the client has to leave; the song has become an ambush. The card turns it into a choice: the client picks when and where they will play it, prepares the body (seated, a warm drink, a blanket, the door closed), listens through once with attention on the sound rather than the story, and writes what came. Then they rate the pain and the comfort, which often arrive together, and decide when to play it next. Watch for a client who plays it on repeat at night; once, prepared, is the practice.', '[{"id": "f0", "type": "textarea", "label": "The song, and where it has ambushed me before:"}, {"id": "f1", "type": "textarea", "label": "When and where I will play it on purpose, and how I will prepare my body:"}, {"id": "f2", "type": "textarea", "label": "Listening through once: what I noticed in the sound itself:"}, {"id": "f3", "type": "textarea", "label": "What came with it: the pain (0 to 10) and the comfort (0 to 10):"}, {"id": "f4", "type": "textarea", "label": "What I did in the five minutes after the song ended:"}, {"id": "f5", "type": "textarea", "label": "When I will play it next, and whether I will play it with anyone:"}]'::jsonb, array['grief and loss', 'self-soothing', 'core DBT']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('memory-window-sun-catcher-craft', 'Memory Window Sun Catcher Craft', 'kids'::resource_kind, 'A tissue paper sun catcher the child makes in the colors of a person or pet who has died, hung where the light comes in.', 'Use it to give a grieving child a way to make something bright about the person and talk while their hands are busy.', array['Children']::text[], '30 minutes', 'The child cuts a frame from black paper (the parent helps with scissors), sticks clear contact paper to the back, and presses on torn pieces of tissue in colors they choose for the person or pet: their favorite color, the color of their car, their eyes, their garden. While they work, the parent asks easy questions (what color was their kitchen, what did they always wear) and lets the child talk or not. Watch for a parent who corrects the child''s memories; the colors are the child''s, and so are the stories.', '[{"id": "f0", "type": "textarea", "label": "Draw your sun catcher here and write what each color is for:"}, {"id": "f1", "type": "textarea", "label": "What do you remember about the person or pet that the colors tell?"}, {"id": "f2", "type": "textarea", "label": "Which window did you choose, and what time of day does the light come through?"}, {"id": "f3", "type": "textarea", "label": "Grown-up: what my child said while their hands were busy, in their words:"}, {"id": "f4", "type": "textarea", "label": "What would you like to say to them when the sun comes through?"}]'::jsonb, array['grief and loss', 'children', 'craft']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('friend-who-only-calls-when-they-need-something-sheet', 'Friend Who Only Calls When They Need Something Sheet', 'worksheet'::resource_kind, 'A sheet for the one-sided friendship, counting what flows each way and deciding what the client wants to do about it.', 'Use it to help a client see a lopsided friendship clearly and choose between naming it, rebalancing it or letting it shrink.', array['Adults', 'Teens']::text[], '25 minutes', 'The phone rings and the client knows before answering that a favor is coming. The sheet has them list the last ten contacts with this friend and who started each one and why, then what they value about the friendship anyway, and what they have never said about the imbalance. Then the options: say it plainly, start saying no to some asks, ask for something themselves and see what happens, or let the friendship take the shape it has without resentment. Watch for a client who assumes the friend knows; the sheet has them check whether it has ever been said.', '[{"id": "f0", "type": "textarea", "label": "The last ten contacts with this friend: who started each one, and what it was about:"}, {"id": "f1", "type": "textarea", "label": "What I value about this friendship anyway:"}, {"id": "f2", "type": "textarea", "label": "What I have never said about the imbalance, written out:"}, {"id": "f3", "type": "textarea", "label": "My options: name it, say no to some asks, ask for something myself, or accept the shape it has:"}, {"id": "f4", "type": "textarea", "label": "The one I am choosing, and the first sentence or action:"}, {"id": "f5", "type": "textarea", "label": "After a month: what changed, and whether I would choose the same again:"}]'::jsonb, array['relationship issues', 'boundaries', 'decisions']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('they-forgot-our-plans-so-i-do-not-matter-thought-record', 'They Forgot Our Plans So I Do Not Matter Thought Record', 'cbt'::resource_kind, 'A thought record for the moment a friend or partner forgets a plan and the client reads it as a measure of their worth.', 'Use it to catch the jump from a forgotten plan to a verdict about how much the client matters to the other person.', array['Adults', 'Teens']::text[], '20 minutes', 'A forgotten dinner or call stings, and within the hour it has become proof: if I mattered, they would have remembered. The record has the client write what happened, the thought and the belief in it, the feeling, and then the evidence: how this person has shown up at other times, what else was going on in their week, what the client has forgotten themselves and what it meant about their own caring, and whether mattering and remembering are the same thing. Watch for a client who says nothing and withdraws; the record has them write the sentence.', '[{"id": "f0", "type": "textarea", "label": "What was planned, what happened, and how I found out:"}, {"id": "f1", "type": "textarea", "label": "The thought about what it meant, and how much I believed it (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "What I felt, and what I did in the first hour:"}, {"id": "f3", "type": "textarea", "label": "How this person has shown up other times, and what else was in their week:"}, {"id": "f4", "type": "textarea", "label": "Plans I have forgotten, and what that meant about my caring:"}, {"id": "f5", "type": "textarea", "label": "A balanced thought, and the plain sentence I will say to them:"}]'::jsonb, array['relationship issues', 'thought record', 'thinking traps']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('rehearsing-the-comeback-or-hearing-them-out-page', 'Rehearsing the Comeback or Hearing Them Out Page', 'act'::resource_kind, 'A choice point page for the moment in an argument when the client is composing their reply instead of listening.', 'Use it to help a client notice the comeback forming and choose, by values, to hear the other person out first.', array['Adults', 'Teens']::text[], '15 minutes', 'In most arguments the client stops listening about ten seconds in and starts drafting. The page has them recall a recent one: the moment the drafting started, what the comeback was, and what they missed while composing it. Then the choice point: on one side, the comeback and what it gets (being right, the last word); on the other, hearing them out and what that serves (the relationship, understanding, being the person they want to be). Watch for a client who agrees to listen and plans to deliver the comeback afterward anyway; the page asks what the comeback is for.', '[{"id": "f0", "type": "textarea", "label": "A recent argument: the moment I started drafting my reply, and what I missed:"}, {"id": "f1", "type": "textarea", "label": "The comeback I was composing, and what it would have gotten me:"}, {"id": "f2", "type": "textarea", "label": "What hearing them out would have served instead:"}, {"id": "f3", "type": "textarea", "label": "The move I will make the next time I notice I am drafting:"}, {"id": "f4", "type": "textarea", "label": "What the comeback is for, honestly, and whether I still want it:"}, {"id": "f5", "type": "textarea", "label": "The next disagreement: when I noticed drafting, and what I did:"}]'::jsonb, array['relationship issues', 'choice point', 'values']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('dear-man-for-splitting-the-dinner-bill-with-friends-card', 'DEAR MAN for Splitting the Dinner Bill With Friends Card', 'dbt'::resource_kind, 'A DEAR MAN card for the moment the bill arrives and the client always pays more than their share rather than speak.', 'Use it to give a client a script for a small, recurring money moment with friends that leaves them resentful.', array['Adults', 'Teens']::text[], '15 minutes', 'The bill comes, someone says let''s split it evenly, and the client who had a salad and water pays for the steak and the cocktails again. The card has the client write each line for this scene (I had the salad; I would rather pay for what I ordered; can we each cover our own; that way nobody is keeping score), the moment they will say it (when the bill is requested, not when it arrives), and the negotiation if the group pushes back. Rehearse aloud. Watch for a client who scripts it and then pays anyway; ask what the resentment costs the friendship.', '[{"id": "f0", "type": "textarea", "label": "Describe: the facts of what I ordered and what the split would have me pay:"}, {"id": "f1", "type": "textarea", "label": "Express: how I feel about paying more than my share, in one line:"}, {"id": "f2", "type": "textarea", "label": "Assert: exactly what I am asking for:"}, {"id": "f3", "type": "textarea", "label": "Reinforce: why this works for everyone:"}, {"id": "f4", "type": "textarea", "label": "Mindful, confident, negotiate: how I will stay on point, how I will sound, and my fallback:"}, {"id": "f5", "type": "textarea", "label": "The next dinner: when I said it, what happened, and what I paid:"}]'::jsonb, array['relationship issues', 'DEAR MAN', 'money']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('who-brings-up-the-hard-topic-rotation-sheet-for-partners', 'Who Brings Up the Hard Topic Rotation Sheet for Partners', 'couples'::resource_kind, 'A rotation sheet for the couple where one partner always has to raise the difficult subjects and the other waits.', 'Use it to share the job of starting hard conversations so one partner is not always the one who ruins the evening.', array['Couples']::text[], '30 minutes', 'In many couples one partner is the one who says we need to talk, and the other is relieved not to be, and resentful of how it comes out. The sheet has each partner write what it is like to be in their role, lists the hard topics currently waiting, and sets a rotation: the waiting partner raises the next one, with a time and a first sentence agreed in advance so it is not an ambush. The raising partner gets a turn at being the one who is approached. Watch for the waiting partner raising a small topic and calling it done; the list says which topics count.', '[{"id": "f0", "type": "textarea", "label": "Partner who usually raises things: what it is like to always be the one:"}, {"id": "f1", "type": "textarea", "label": "Partner who usually waits: what it is like to be approached, and why I wait:"}, {"id": "f2", "type": "textarea", "label": "The hard topics currently waiting, listed by both of us:"}, {"id": "f3", "type": "textarea", "label": "The rotation: who raises the next one, when, and the first sentence they will use:"}, {"id": "f4", "type": "textarea", "label": "After each conversation: how it went compared to our usual pattern:"}, {"id": "f5", "type": "textarea", "label": "What each of us learned from the other''s role:"}]'::jsonb, array['relationship issues', 'couples', 'communication']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('dentist-chair-reclined-position-comfort-plan-sheet', 'Dentist Chair Reclined Position Comfort Plan Sheet', 'worksheet'::resource_kind, 'A comfort plan for the dentist, where lying back with someone''s hands near the face can be hard for a survivor.', 'Use it to help a client plan a dental visit so the position, the pacing and the stop signal are agreed in advance.', array['Adults', 'Teens']::text[], '20 minutes before the appointment', 'The dentist''s chair is a known hard place for many survivors: reclined, mouth open, someone leaning over, no easy way to speak. The sheet has the client decide what they will tell the office in advance (as little as they like: I need breaks, I need to sit up between steps, I need to know before you touch), the hand signal for stop, the position of the chair they can tolerate, what they will hold or listen to, and who comes with them. Nothing on the sheet asks about the past; it stays with the chair. Watch for a client who plans to tough it out silently; the signal is the point.', '[{"id": "f0", "type": "textarea", "label": "What I will tell the office in advance, in my own words, and how (phone, form, in person):"}, {"id": "f1", "type": "textarea", "label": "My stop signal, and my sit-up signal, agreed with the dentist before the first touch:"}, {"id": "f2", "type": "textarea", "label": "The chair position I can tolerate, and what I will hold or listen to:"}, {"id": "f3", "type": "textarea", "label": "Who comes with me, and where they will be in the room:"}, {"id": "f4", "type": "textarea", "label": "What I will do in the ten minutes after the appointment:"}, {"id": "f5", "type": "textarea", "label": "Afterward: what helped, and what I will ask for next time:"}]'::jsonb, array['sexual abuse', 'safety', 'planning']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('it-was-my-fault-because-i-did-not-fight-gentle-check-sheet', 'It Was My Fault Because I Did Not Fight Gentle Check Sheet', 'cbt'::resource_kind, 'A gentle check for the self-blame that attaches to not fighting back, done in session and kept to the belief rather than the events.', 'Use it to look with a client at the rule that freezing equals consent or fault, without revisiting the details of what happened.', array['Adults', 'Teens']::text[], 'Full session, in session only', 'The belief is common and corrosive: I did not fight, so it was my fault. The sheet stays with the belief and away from the events. The client states the rule, rates the belief, and looks at it from the outside: what they know about how bodies respond under threat, what they would say to another person who froze, where the responsibility for an act sits, and whether they would apply the rule to a child. Do this in session, go slowly, and stop if the client begins to recount details; the sheet does not ask for them. If anything suggests current risk, name 988 (call or text) and the safety plan.', '[{"id": "f0", "type": "textarea", "label": "The rule as it stands in my mind, in one sentence:"}, {"id": "f1", "type": "textarea", "label": "How much I believe it right now (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "What I know about how bodies respond when they are frightened:"}, {"id": "f3", "type": "textarea", "label": "What I would say to another person who told me this rule about themselves:"}, {"id": "f4", "type": "textarea", "label": "Where the responsibility for an act sits, in my own words:"}, {"id": "f5", "type": "textarea", "label": "A one-line statement I can stand behind, and who I can call, including 988 (call or text), if this gets heavy:"}]'::jsonb, array['sexual abuse', 'core beliefs', 'self-blame']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('taking-back-the-word-no-values-page', 'Taking Back the Word No Values Page', 'act'::resource_kind, 'A values page about the word no: where the client wants to be able to say it, and the small places to start.', 'Use it to help a survivor reclaim no as an ordinary, available word in daily life, starting far from the hardest places.', array['Adults', 'Teens']::text[], '20 minutes', 'For many survivors the word no has become heavy, unsafe or useless, and it disappears from ordinary life: the extra shift, the hug from a relative, the second helping. The page has the client list where no has gone missing, what they value that a working no would protect (rest, their body, their time, their say), and the smallest places to practice it this week: a telemarketer, a sample at the store, a plan they do not want. The page stays in the present and never asks about the past. Watch for a client who starts with the hardest person; the page is built from the easiest outward.', '[{"id": "f0", "type": "textarea", "label": "Where the word no has gone missing from my ordinary life:"}, {"id": "f1", "type": "textarea", "label": "What a working no would protect for me:"}, {"id": "f2", "type": "textarea", "label": "The three smallest places I could practice it this week:"}, {"id": "f3", "type": "textarea", "label": "Each no I said: where, to whom, and what happened:"}, {"id": "f4", "type": "textarea", "label": "What it was like in my body to say it:"}, {"id": "f5", "type": "textarea", "label": "The next place outward where I will try it:"}]'::jsonb, array['sexual abuse', 'values', 'boundaries']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('observe-the-room-five-exits-grounding-card', 'Observe the Room Five Exits Grounding Card', 'dbt'::resource_kind, 'A grounding card for the client who needs to know the exits before they can settle, turning the scan into a calm observe skill.', 'Use it to turn an anxious exit scan into a deliberate, finished observation so the client can then be in the room.', array['Adults', 'Teens']::text[], '10 minutes to learn, two minutes to use', 'Many survivors scan every room for exits and keep scanning all evening. The card does not take the scan away; it finishes it. On entering, the client observes and names, silently, the exits, the people, the light and one pleasant detail, in that order, then says to themselves: observed, done. If the urge to re-scan returns, they name it (there is the urge) and return attention to the pleasant detail or the conversation. They practice in session with the room they are in. Watch for a client who treats the card as permission to scan more; it is one scan, then the room.', '[{"id": "f0", "type": "textarea", "label": "The rooms where I scan most, and how long the scanning usually lasts:"}, {"id": "f1", "type": "textarea", "label": "My observe list in order: exits, people, light, one pleasant detail:"}, {"id": "f2", "type": "textarea", "label": "The words I will say to myself when the list is finished:"}, {"id": "f3", "type": "textarea", "label": "What I will do when the urge to re-scan returns:"}, {"id": "f4", "type": "textarea", "label": "Three rooms this week: how long the scan took, and what I did after observed, done:"}, {"id": "f5", "type": "textarea", "label": "What I noticed in those rooms that I would have missed while scanning:"}]'::jsonb, array['sexual abuse', 'grounding', 'mindfulness']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('safety-team-superhero-badges-craft', 'Safety Team Superhero Badges Craft', 'kids'::resource_kind, 'A craft where the child makes a badge for each grown-up on their safety team and says what each one''s power is.', 'Use it to help a child name their trusted adults in a playful way and rehearse who they would tell about a worry.', array['Children']::text[], '30 minutes', 'The child cuts badge shapes from card, one for each grown-up they trust (a parent, a teacher, a grandparent, a coach), decorates each with the person''s name and a superpower (good at listening, always picks up the phone, believes me). The parent helps with names and asks what makes each person safe to tell things to. Keep the play about telling and listening, never about details of anything that happened. If the child discloses during the craft, stay calm, listen, and remember your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Draw your badges here with each grown-up''s name and superpower:"}, {"id": "f1", "type": "textarea", "label": "What makes each person on your team safe to tell things to?"}, {"id": "f2", "type": "textarea", "label": "If something made you feel yucky or confused, which badge would you go to first? What would you say?"}, {"id": "f3", "type": "textarea", "label": "Grown-up: what my child said about who they would tell, and how I responded:"}, {"id": "f4", "type": "textarea", "label": "Where will the badges live so you can see your team every day?"}]'::jsonb, array['sexual abuse', 'children', 'safety']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('coping-skill-handoff-when-one-stops-working-sheet', 'Coping Skill Handoff When One Stops Working Sheet', 'worksheet'::resource_kind, 'A handoff sheet for the moment a reliable coping skill stops working, with the next skill ready to take over.', 'Use it to stop a client abandoning coping altogether when their favorite skill fails, by planning the handoff in advance.', array['Adults', 'Teens']::text[], '20 minutes', 'Every skill stops working sometimes: the walk does not settle, the breathing feels silly, the call goes to voicemail. Clients then conclude that nothing works. The sheet has them list their go-to skills, the signs that one has stopped working in the moment (how long they give it, what they notice), and the handoff: which skill takes over from which, and what they say to themselves at the handoff instead of giving up. They record one real handoff. Watch for a client who gives a skill thirty seconds before calling it failed; the sheet asks for a fair trial time for each.', '[{"id": "f0", "type": "textarea", "label": "My go-to coping skills, in the order I usually reach for them:"}, {"id": "f1", "type": "textarea", "label": "The signs that a skill has stopped working in the moment, and the fair trial I will give it:"}, {"id": "f2", "type": "textarea", "label": "The handoff: which skill takes over from which:"}, {"id": "f3", "type": "textarea", "label": "What I will say to myself at the handoff instead of nothing works:"}, {"id": "f4", "type": "textarea", "label": "One real handoff this week: what failed, what took over, and what happened:"}, {"id": "f5", "type": "textarea", "label": "The skill I most need a backup for, and what that backup will be:"}]'::jsonb, array['coping skills', 'planning', 'self-monitoring']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('skills-should-work-instantly-belief-check-sheet', 'Skills Should Work Instantly Belief Check Sheet', 'cbt'::resource_kind, 'A belief check for the expectation that a coping skill should bring relief at once, or it is not working.', 'Use it to reset a client''s timeline for coping skills and to compare the expected relief with the real curve.', array['Adults', 'Teens']::text[], '20 minutes', 'A client tries a skill, feels no different after a minute, and drops it. The sheet states the belief (if it works, I will feel it right away), rates it, and then looks at evidence: how long other things take to work (a hot bath, a hard conversation, a workout), what the client has noticed on the times they stayed with a skill longer, and what a coach would say about a skill practiced once. Then a timed test of one skill with distress rated at the start, midpoint and end. Watch for the client who stays with a skill that is wrong for the moment; timing and fit are both on the sheet.', '[{"id": "f0", "type": "textarea", "label": "The belief about how fast a skill should work, and how much I hold it (0 to 100):"}, {"id": "f1", "type": "textarea", "label": "Other things in my life that take time to work, and how long they take:"}, {"id": "f2", "type": "textarea", "label": "Times I stayed with a skill longer than usual, and what happened:"}, {"id": "f3", "type": "textarea", "label": "The test: the skill, the fixed time, and my distress at the start, midpoint and end:"}, {"id": "f4", "type": "textarea", "label": "What the curve looked like, compared with what I expected:"}, {"id": "f5", "type": "textarea", "label": "A balanced belief about how long to give a skill before judging it:"}]'::jsonb, array['coping skills', 'core beliefs', 'behavioral experiment']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('coping-skill-as-a-life-jacket-not-a-boat-page', 'Coping Skill as a Life Jacket Not a Boat Page', 'act'::resource_kind, 'An ACT page that makes a coping skill the thing that keeps a client afloat while they swim, not the thing that carries them.', 'Use it to reset what a client expects from coping skills and to point them at the shore they are swimming toward.', array['Adults', 'Teens']::text[], '15 minutes', 'A life jacket keeps you up; it does not get you anywhere. A client who expects a skill to carry them is disappointed when they are still in the water. The page has the client name the water they are in, the skills that keep them afloat, and the shore: what they would be swimming toward if staying afloat were handled. Then one stroke this week, with the jacket on, toward that shore. The last prompt asks what they have been waiting for a boat to do that they could begin swimming toward. Watch for a client who takes this as a reason to drop the jacket; the jacket stays on.', '[{"id": "f0", "type": "textarea", "label": "The water I am in right now, described plainly:"}, {"id": "f1", "type": "textarea", "label": "The skills that keep me afloat, and how well each one does it:"}, {"id": "f2", "type": "textarea", "label": "The shore: what I would be moving toward if staying afloat were handled:"}, {"id": "f3", "type": "textarea", "label": "One stroke toward it this week, with the jacket on:"}, {"id": "f4", "type": "textarea", "label": "What I have been waiting for a boat to do that I could begin swimming toward:"}, {"id": "f5", "type": "textarea", "label": "After the stroke: what happened, and whether the jacket held:"}]'::jsonb, array['coping skills', 'metaphor', 'committed action']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('accepts-thoughts-counting-backward-by-sevens-card', 'ACCEPTS Thoughts Counting Backward by Sevens Card', 'dbt'::resource_kind, 'An ACCEPTS card using the thoughts strategy: counting backward from 300 by sevens to crowd out a spiral.', 'Use it to give a client a portable, invisible mental task that takes enough attention to interrupt a spiral.', array['Adults', 'Teens']::text[], '5 minutes to learn, used in the moment', 'The T in ACCEPTS is thoughts: a mental task hard enough to take up the room a spiral wants. Counting backward by sevens from 300 is the classic, and nobody can see it being done. The card has the client try it in session (300, 293, 286) for two minutes, rate the spiral before and after, and pick two alternatives for when sevens get too easy: naming a capital for each letter, recalling the lineup of a team, reciting song lyrics backward. Watch for a client who uses it to avoid every feeling; it is for the spiral, not for the day.', '[{"id": "f0", "type": "textarea", "label": "The spiral I most want to interrupt, and where it tends to happen:"}, {"id": "f1", "type": "textarea", "label": "The practice in session: how far I got in two minutes, and the spiral before and after (0 to 10):"}, {"id": "f2", "type": "textarea", "label": "Two alternatives for when sevens get too easy:"}, {"id": "f3", "type": "textarea", "label": "Where I will use it this week:"}, {"id": "f4", "type": "textarea", "label": "Each use: where, how far I counted, and what the spiral did:"}, {"id": "f5", "type": "textarea", "label": "What I did after the counting, once the spiral had loosened:"}]'::jsonb, array['coping skills', 'ACCEPTS', 'distress tolerance']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('coping-skill-pictionary-draw-and-guess-game', 'Coping Skill Pictionary Draw and Guess Game', 'game'::resource_kind, 'A drawing game where players sketch a coping skill without words and the team guesses it, then names when they would use it.', 'Use it to get a group recalling coping skills fast and connecting each one to a moment it would fit.', array['Groups', 'Teens', 'Children']::text[], '30 minutes', 'Coping skills go on slips in a hat (slow breathing, calling a friend, a walk, a cold drink, saying no, writing it down). Teams take turns: a player draws a slip and sketches it on a board, no letters or words, while the team guesses within sixty seconds. A point for the guess, and a bonus point if the team can name one moment this week when that skill would have fit. Debrief: which skills were easy to draw and which were hard, which ones nobody uses, and which one each player will use before the next session. Watch for drawings that mock a skill; redraw it straight.', '[{"id": "f0", "type": "textarea", "label": "The skills my team drew, and which ones we guessed:"}, {"id": "f1", "type": "textarea", "label": "The skill that was hardest to draw, and why:"}, {"id": "f2", "type": "textarea", "label": "The moments this week we named for the bonus points:"}, {"id": "f3", "type": "textarea", "label": "A skill in the hat that nobody in the group actually uses, and why:"}, {"id": "f4", "type": "textarea", "label": "Debrief: the one skill I will use before next session, and when:"}]'::jsonb, array['coping skills', 'game', 'group']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('blood-draw-appointment-step-plan-sheet', 'Blood Draw Appointment Step Plan Sheet', 'worksheet'::resource_kind, 'A step plan for a blood draw, from booking it to walking out, for a client who has been putting it off for months.', 'Use it to get an avoided blood test booked and done, with the steps, the body and the stop signal planned in advance.', array['Adults', 'Teens']::text[], '25 minutes before the appointment', 'A blood draw is a routine thing that some clients avoid for years, and the cost grows quietly. The sheet breaks it into steps: booking, the night before, the waiting room, the chair, the needle, the minute after. For each step the client writes what they fear, what they will do with their body (applied tension if they get faint, looking away or watching by choice), and what they will say to the person drawing the blood. Watch for a client who plans the whole thing and leaves the booking step blank; booking is step one and gets a date.', '[{"id": "f0", "type": "textarea", "label": "Booking: the date I will call or book online, and what I will tell them I need:"}, {"id": "f1", "type": "textarea", "label": "The night before and the morning of: what I will eat, drink and tell myself:"}, {"id": "f2", "type": "textarea", "label": "The waiting room: what I will do with the minutes:"}, {"id": "f3", "type": "textarea", "label": "The chair and the needle: what I will do with my body and eyes, and what I will say to the person:"}, {"id": "f4", "type": "textarea", "label": "The minute after: what I will do before standing up:"}, {"id": "f5", "type": "textarea", "label": "Afterward: what actually happened at each step, and what I will do next time:"}]'::jsonb, array['phobias', 'exposure', 'planning']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('the-dog-off-leash-will-attack-prediction-sheet', 'The Dog Off Leash Will Attack Prediction Sheet', 'cbt'::resource_kind, 'A prediction sheet for the client who crosses the street for every unleashed dog, testing the attack forecast.', 'Use it to put the prediction about an approaching dog against the client''s own record of every dog they have passed.', array['Adults', 'Teens', 'Children']::text[], '20 minutes', 'An unleashed dog in the park sets off a prediction (it will run at me, it will bite) and a detour that can add half an hour to a walk. The sheet has the client write the prediction and the belief in it, then the record: how many dogs they have been near in the past year, how many ran at them, how many bit. Then what they know about what dogs mostly do when they approach a stranger, and what the dog''s owner is usually doing. Watch for a client with a history of an actual bite; the record still counts, but go slower.', '[{"id": "f0", "type": "textarea", "label": "The prediction when I see a dog off leash, and how much I believe it (0 to 100):"}, {"id": "f1", "type": "textarea", "label": "My record: dogs I have been near in a year, how many ran at me, how many bit:"}, {"id": "f2", "type": "textarea", "label": "What dogs mostly do when they come up to a stranger, from what I have actually seen:"}, {"id": "f3", "type": "textarea", "label": "A balanced prediction for the next dog:"}, {"id": "f4", "type": "textarea", "label": "My plan for the next dog: what I will do with my body and feet:"}, {"id": "f5", "type": "textarea", "label": "The next dog: what it did, what I did, and what the prediction said versus what happened:"}]'::jsonb, array['phobias', 'predictions', 'exposure']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('fear-of-heights-on-the-parking-garage-top-level-page', 'Fear of Heights on the Parking Garage Top Level Page', 'act'::resource_kind, 'A willingness page for the top level of a parking garage, a place a client can reach by elevator and leave at any time.', 'Use it to help a client practice being near an edge with the fear present, in a place that is high, safe and ordinary.', array['Adults', 'Teens']::text[], '15 minutes to plan, then the visit', 'The top level of a parking garage is a useful practice ground: high, fenced, with a car to retreat to and an elevator down. The page has the client name what fear says will happen at the rail, their willingness to stand there with that fear for two minutes (0 to 10), and what they would be able to do in life if heights stopped deciding (the hotel room upstairs, the hike, the stadium seat). Watch for a client who grips the rail white-knuckled the whole time; the practice is to stand, not to brace.', '[{"id": "f0", "type": "textarea", "label": "What fear says will happen at the rail:"}, {"id": "f1", "type": "textarea", "label": "My willingness to stand there with the fear for two minutes (0 to 10), and what makes it that number:"}, {"id": "f2", "type": "textarea", "label": "What I could do in life if heights stopped deciding for me:"}, {"id": "f3", "type": "textarea", "label": "The visit plan: where I will start, how long I will stay, what my hands and eyes will do:"}, {"id": "f4", "type": "textarea", "label": "What the fear did over the two minutes:"}, {"id": "f5", "type": "textarea", "label": "The next height, a little higher or a little closer to the edge:"}]'::jsonb, array['phobias', 'willingness', 'exposure']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('check-the-facts-on-the-spider-in-the-corner-card', 'Check the Facts on the Spider in the Corner Card', 'dbt'::resource_kind, 'A check the facts card for the spider in the corner of the room that the client cannot stop watching.', 'Use it to help a client separate the emotion about a spider from the facts about it, and decide what to do by the facts.', array['Adults', 'Teens']::text[], '10 minutes', 'A spider in the corner can end an evening: the client watches it, cannot read, cannot sleep in the room. Check the facts asks what the emotion is, what event set it off, what the interpretation is (it will come to me, it is dangerous), what the facts actually are (where house spiders go, what the ones in this region do, how far it is from the bed), and whether the emotion and its size fit the facts. Watch for a client who checks the facts and then cannot act on them; the last line is the action.', '[{"id": "f0", "type": "textarea", "label": "The emotion and its size (0 to 10), and the spider that set it off:"}, {"id": "f1", "type": "textarea", "label": "My interpretation: what I think the spider is going to do:"}, {"id": "f2", "type": "textarea", "label": "The facts: what spiders like this one do, and how far it is from me:"}, {"id": "f3", "type": "textarea", "label": "Does the emotion fit the facts? Does its size?"}, {"id": "f4", "type": "textarea", "label": "What I will do by the facts: leave it, move it with a cup, or ask someone:"}, {"id": "f5", "type": "textarea", "label": "The next spider: what I did, and how long the evening was lost to it:"}]'::jsonb, array['phobias', 'check the facts', 'core DBT']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('approach-steps-simon-says-brave-edition-game', 'Approach Steps Simon Says Brave Edition Game', 'game'::resource_kind, 'A Simon Says game where the commands are small approach steps toward a feared thing, with the player allowed to pass.', 'Use it to get a group taking small brave steps in a playful frame, each at their own level, with a debrief on what happened.', array['Groups', 'Children', 'Teens']::text[], '25 minutes', 'The leader has the feared object or a picture of it (a toy spider, a photo of a dog, a balloon for those who fear pops) at one end of the room. Simon says: take one step closer, look at it for three seconds, point at it, say its name, touch the table it is on. A player may say pass at any command and stay where they are, and nobody is out for passing; the group cheers a pass as loudly as a step because both are honest. Debrief: which command was the hardest, what the body did, and what each player will try outside. Watch for a leader or peer who pushes past a pass.', '[{"id": "f0", "type": "textarea", "label": "The feared thing I was approaching, and where I started:"}, {"id": "f1", "type": "textarea", "label": "The commands I did, and the ones I passed on:"}, {"id": "f2", "type": "textarea", "label": "The hardest command, and what my body did when Simon said it:"}, {"id": "f3", "type": "textarea", "label": "What the fear did between round one and round three:"}, {"id": "f4", "type": "textarea", "label": "Debrief: the step I will try outside the game this week:"}]'::jsonb, array['phobias', 'game', 'exposure']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('changing-room-lighting-and-mirrors-plan-sheet', 'Changing Room Lighting and Mirrors Plan Sheet', 'worksheet'::resource_kind, 'A plan for the store changing room, where harsh light and three-way mirrors turn a shopping trip into an hour of judgment.', 'Use it to help a client shop for clothes with a plan for the changing room instead of avoiding stores or leaving upset.', array['Adults', 'Teens']::text[], '20 minutes', 'The changing room has the worst lighting and the most mirrors of any room the client enters, and many leave it having bought nothing and feeling terrible. The sheet has the client plan the trip: what they are shopping for, how many items they will take in, the rule for the mirror (check the fit of the clothes, not the body), the time limit per item, what they will say to themselves under the light, and what they will do if the judging starts. Watch for a client who plans to shop only online forever; the sheet is about the room.', '[{"id": "f0", "type": "textarea", "label": "What I am shopping for, and how many items I will take into the room:"}, {"id": "f1", "type": "textarea", "label": "My mirror rule: what I am checking, and what I am not:"}, {"id": "f2", "type": "textarea", "label": "The time limit per item, and what I will say to myself under the light:"}, {"id": "f3", "type": "textarea", "label": "What I will do if the judging starts: leave the room, call someone, move on to the next item:"}, {"id": "f4", "type": "textarea", "label": "A store with kinder rooms, or a plan to try things on at home:"}, {"id": "f5", "type": "textarea", "label": "After the trip: what I bought, what the room was like, and what I would change:"}]'::jsonb, array['body image', 'planning', 'self-talk']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('everyone-is-looking-at-my-arms-thought-record', 'Everyone Is Looking at My Arms Thought Record', 'cbt'::resource_kind, 'A thought record for the certainty that a particular body part is what everyone in the room is looking at.', 'Use it to test a client''s belief about where others'' attention goes, against what the client knows about attention in a room.', array['Adults', 'Teens']::text[], '20 minutes', 'The client wears long sleeves in August because everyone, they are certain, is looking at their arms. The record has them write the situation, the thought and the belief in it, the feeling, and then the evidence: what they themselves notice about other people''s arms, what people in a room are actually attending to (their own concerns, their phones, the conversation), and whether anyone has ever said anything. Watch for a client who counts every glance as a judgment; the sheet asks what else a glance could be.', '[{"id": "f0", "type": "textarea", "label": "The situation, and the thought about who was looking and at what:"}, {"id": "f1", "type": "textarea", "label": "My belief in it (0 to 100), and what I felt and did:"}, {"id": "f2", "type": "textarea", "label": "What I notice about other people''s arms, or whatever the part is, in a typical hour:"}, {"id": "f3", "type": "textarea", "label": "What people in a room are actually attending to, as far as I can tell:"}, {"id": "f4", "type": "textarea", "label": "A balanced thought about where attention goes:"}, {"id": "f5", "type": "textarea", "label": "The experiment: where I let the part show, how many looks I counted, and what else a look could have been:"}]'::jsonb, array['body image', 'thought record', 'thinking traps']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('body-as-a-teammate-not-a-project-page', 'Body as a Teammate Not a Project Page', 'act'::resource_kind, 'An ACT page that moves the body from a project to be fixed to a teammate the client works alongside.', 'Use it to shift how a client relates to their body, from manager to teammate, and to act on that shift this week.', array['Adults', 'Teens']::text[], '15 minutes', 'Many clients treat their body as a project with a deadline, and the project is never finished. The page offers a teammate instead: someone who carried them up the stairs today, got them through the night, held the child. The client writes what the body did for them this week as a teammate would, what they said to it as a manager would, and how they would speak to a human teammate who had done the same work. Then one way they will treat the body as a teammate this week: rest when it asks, a walk it enjoys, a thank you. Watch for a client who turns the teammate into a project with a new goal.', '[{"id": "f0", "type": "textarea", "label": "What my body did for me this week, listed the way I would list a teammate''s work:"}, {"id": "f1", "type": "textarea", "label": "What I said to my body this week, the way a manager talks about a project:"}, {"id": "f2", "type": "textarea", "label": "How I would speak to a human teammate who had done the same work:"}, {"id": "f3", "type": "textarea", "label": "One way I will treat my body as a teammate this week:"}, {"id": "f4", "type": "textarea", "label": "After I did it: what my body did, and what my mind said:"}, {"id": "f5", "type": "textarea", "label": "What my body and I are working on together, as teammates, that is not about how it looks:"}]'::jsonb, array['body image', 'self-compassion', 'values']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('describe-not-judge-the-group-photo-card', 'Describe Not Judge the Group Photo Card', 'dbt'::resource_kind, 'A describe skill card for the group photo the client has been tagged in, replacing judgments with plain description.', 'Use it to help a client look at a photo of themselves with others and describe what is there without the running verdict.', array['Adults', 'Teens']::text[], '10 minutes', 'The group photo arrives and the client sees only one thing in it: themselves, judged. The describe skill asks for what a camera would report, not what the critic says. The card has the client look at the photo and write only observable facts: who is in it, where, what people are doing, what the light is like, what they themselves are doing (laughing, holding a glass, looking at someone). Judgment words are crossed out and replaced with descriptions. Watch for a client who describes everyone else and skips themselves; the self goes in the description too.', '[{"id": "f0", "type": "textarea", "label": "The photo: who is in it, where, and what is happening:"}, {"id": "f1", "type": "textarea", "label": "What I am doing in it, described the way a camera would report it:"}, {"id": "f2", "type": "textarea", "label": "The judgments my mind offered, crossed out, and the description that replaces each:"}, {"id": "f3", "type": "textarea", "label": "How the photo felt before describing it and after (0 to 10):"}, {"id": "f4", "type": "textarea", "label": "What I will do with the tag:"}, {"id": "f5", "type": "textarea", "label": "The next photo: how quickly the judgment came, and whether I described first:"}]'::jsonb, array['body image', 'describe', 'mindfulness']::text[], '2026-11-21T15:00:00+00:00'::timestamptz),
  ('photo-taking-and-posting-consent-pact-for-partners', 'Photo Taking and Posting Consent Pact for Partners', 'couples'::resource_kind, 'A pact for partners about taking and posting photos of each other, so neither is surprised by a picture they hate.', 'Use it to settle how a couple takes, shares and posts photos of each other when one partner finds photos of themselves hard.', array['Couples']::text[], '25 minutes', 'One partner loves to post the trip; the other sees the photo on their feed and spends the evening undone by it. The sheet has the partner who struggles with photos write what the hard part is (being caught unposed, the angle, the audience, not being asked) and what would make it fine (a look before posting, a veto, more candid or less candid). The posting partner writes what the photos mean to them and what they fear losing if they ask first. Watch for a rule that forbids all photos; the pact is about consent, not absence.', '[{"id": "f0", "type": "textarea", "label": "Partner who finds photos hard: the hard part, named plainly, and what would make it fine:"}, {"id": "f1", "type": "textarea", "label": "Posting partner: what the photos mean to me, and what I fear losing if I ask first:"}, {"id": "f2", "type": "textarea", "label": "Our rule for taking photos of each other:"}, {"id": "f3", "type": "textarea", "label": "Our rule for posting them, including the look before and the veto:"}, {"id": "f4", "type": "textarea", "label": "The words either of us can use to say take that one down, and the reply:"}, {"id": "f5", "type": "textarea", "label": "After the next trip or event: how the pact held, and one photo we both liked:"}]'::jsonb, array['body image', 'couples', 'communication']::text[], '2026-11-21T15:00:00+00:00'::timestamptz)
